window.GD_DATA={"schema_version":1,"title":"Geometrie descriptivă și desen tehnic — flashcards","language":"ro","generated":"2026-10-11","sources":{"sarbu":"N. D. Sârbu, Geometrie descriptivă și desen tehnic, Ex Terra Aurum, 2017 (ISBN 978-606-8827-04-9). Paginile sunt cele tipărite (identice cu paginile PDF).","curs_extins":"Geometrie descriptivă și desen tehnic — Curs universitar extins (material de studiu independent). Paginile sunt cele din PDF."},"units":[{"unit":1,"title":"Introducere","sarbu_pages":"7–13","book_pdf_pages":"9–15","card_count":32},{"unit":2,"title":"Punctul","sarbu_pages":"14–18","book_pdf_pages":"16–21","card_count":36},{"unit":3,"title":"Dreapta","sarbu_pages":"19–27","book_pdf_pages":"22–42","card_count":40},{"unit":4,"title":"Planul","sarbu_pages":"28–35","book_pdf_pages":"43–57","card_count":39},{"unit":5,"title":"Metodele geometriei descriptive","sarbu_pages":"36–43","book_pdf_pages":"58–67","card_count":33},{"unit":6,"title":"Reprezentarea corpurilor geometrice","sarbu_pages":"44–48","book_pdf_pages":"68–74","card_count":25},{"unit":7,"title":"Reprezentarea corpurilor de rotație","sarbu_pages":"49–52","book_pdf_pages":"75–80","card_count":21},{"unit":8,"title":"Secțiuni cu plane. Intersecția suprafețelor","sarbu_pages":"53–56","book_pdf_pages":"81–88","card_count":23},{"unit":9,"title":"Desfășurarea suprafețelor","sarbu_pages":"57–60","book_pdf_pages":"89–98","card_count":22},{"unit":10,"title":"Scopul și importanța desenului tehnic","sarbu_pages":"61–71","book_pdf_pages":"99–110","card_count":74}],"card_types":{"definitie":"Definiție / regulă","recunoastere":"Recunoaștere","procedeu":"Procedeu","formula":"Formulă","capcana":"Capcană","explicativ":"Explicație","lucrare":"Lucrare de verificare"},"cards":[{"id":"GD-U01-001","unit":1,"type":"definitie","front":"Care sunt cele trei sisteme de proiecție prezentate în curs?","back":"1. proiecția centrală (conică)\n2. proiecția paralelă (cilindrică)\n3. proiecția ortogonală","source":{"kind":"sarbu","page":13},"source_text":"Sârbu (2017), p. 13","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-002","unit":1,"type":"definitie","front":"Ce elemente definesc sistemul de proiecție centrală (conică)?","back":"Planul de proiecție P și un punct fix S din spațiu, numit centrul de proiecție.","source":{"kind":"sarbu","page":7},"source_text":"Sârbu (2017), p. 7","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-003","unit":1,"type":"procedeu","front":"Cum se obține proiecția centrală a unui punct M pe planul P?","back":"Se duce dreapta (proiectanta) SM prin centrul S; proiecția m este intersecția acestei drepte cu planul P. Toate proiectantele trec prin același punct S.","source":{"kind":"curs_extins","pdf_page":9},"source_text":"Curs universitar extins, p. PDF 9","tags":["U01","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U01-004","unit":1,"type":"definitie","front":"Ce elemente definesc sistemul de proiecție paralelă (cilindrică)?","back":"Planul de proiecție P și o direcție de proiecție Δ.","source":{"kind":"sarbu","page":7},"source_text":"Sârbu (2017), p. 7","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-005","unit":1,"type":"definitie","front":"De ce proiecția paralelă poate fi privită ca un caz de proiecție centrală?","back":"Pentru că se consideră centrul de proiecție deplasat la infinit, după direcția Δ.","source":{"kind":"sarbu","page":7},"source_text":"Sârbu (2017), p. 7","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-006","unit":1,"type":"procedeu","front":"Cum se obține proiecția paralelă a punctelor A, B, C?","back":"Prin A, B, C se duc paralele la direcția Δ; proiecțiile a, b, c sunt intersecțiile acestor paralele cu planul P.","source":{"kind":"sarbu","page":7},"source_text":"Sârbu (2017), p. 7","tags":["U01","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U01-007","unit":1,"type":"definitie","front":"Ce este proiecția ortogonală în raport cu proiecția paralelă?","back":"Este cazul particular de proiecție paralelă în care direcția Δ este perpendiculară pe planul de proiecție.","source":{"kind":"curs_extins","pdf_page":9},"source_text":"Curs universitar extins, p. PDF 9","tags":["U01","tip::definitie","sursa::Curs_extins"]},{"id":"GD-U01-008","unit":1,"type":"definitie","front":"De ce este importantă proiecția ortogonală în construcții?","back":"Constituie baza reprezentărilor din tehnica construcțiilor: proiectantul își exprimă concepția, iar executantul o realizează interpretând planurile.","source":{"kind":"sarbu","page":8},"source_text":"Sârbu (2017), p. 8","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-009","unit":1,"type":"definitie","front":"Din ce este format sistemul de referință în spațiu?","back":"Din originea sistemului (punctul O) și trei plane de referință: H (orizontal), V (vertical), W (lateral).","source":{"kind":"sarbu","page":8},"source_text":"Sârbu (2017), p. 8","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-010","unit":1,"type":"definitie","front":"Cum se numesc planele H, V, W și cum se notează?","back":"H = planul orizontal de proiecție\nV = planul vertical de proiecție\nW = planul lateral de proiecție\nPlanele de proiecție se notează cu majusculă.","source":{"kind":"sarbu","page":9},"source_text":"Sârbu (2017), p. 9","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-011","unit":1,"type":"definitie","front":"Ce relație există între planele H, V și W?","back":"Fiecare plan este perpendicular pe celelalte două. V și W sunt verticale și perpendiculare între ele, ambele perpendiculare pe H.","source":{"kind":"sarbu","page":8},"source_text":"Sârbu (2017), p. 8","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-012","unit":1,"type":"definitie","front":"Ce este o axă a sistemului de referință?","back":"Dreapta de intersecție a două plane de proiecție. Axele au o orientare și un punct de origine (O) din care se măsoară distanțele.","source":{"kind":"sarbu","page":9},"source_text":"Sârbu (2017), p. 9","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-013","unit":1,"type":"definitie","front":"Ce este axa OX și ce mărime poartă?","back":"Axa absciselor: intersecția planului H cu planul V (linia de pământ).","source":{"kind":"sarbu","page":9},"source_text":"Sârbu (2017), p. 9","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-014","unit":1,"type":"definitie","front":"Ce este axa OY și ce mărime poartă?","back":"Axa depărtărilor: intersecția planului H cu planul W.","source":{"kind":"sarbu","page":9},"source_text":"Sârbu (2017), p. 9","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-015","unit":1,"type":"definitie","front":"Ce este axa OZ și ce mărime poartă?","back":"Axa cotelor: intersecția planului V cu planul W.","source":{"kind":"sarbu","page":9},"source_text":"Sârbu (2017), p. 9","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-016","unit":1,"type":"definitie","front":"Ce semne au axele OX, OY și OZ în convenția cursului?","back":"OX se consideră cu semnul pozitiv; OY și OZ au ambele semne, pozitiv și negativ.","source":{"kind":"sarbu","page":9},"source_text":"Sârbu (2017), p. 9","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-017","unit":1,"type":"definitie","front":"După ce criteriu se împarte planul H în semiplane și care sunt acestea?","back":"După semnul axei OY:\nHA = orizontal anterior (OY pozitiv)\nHP = orizontal posterior (OY negativ)","source":{"kind":"sarbu","page":10},"source_text":"Sârbu (2017), p. 10","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-018","unit":1,"type":"definitie","front":"După ce criteriu se împarte planul V în semiplane și care sunt acestea?","back":"După semnul axei OZ:\nVS = vertical superior (OZ pozitiv)\nVI = vertical inferior (OZ negativ)","source":{"kind":"sarbu","page":10},"source_text":"Sârbu (2017), p. 10","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-019","unit":1,"type":"definitie","front":"În câte regiuni se împarte planul W și după ce criteriu?","back":"În patru, după semnele axelor OY și OZ:\nWI (OY+, OZ+)\nWII (OY−, OZ+)\nWIII (OY−, OZ−)\nWIV (OY+, OZ−)","source":{"kind":"sarbu","page":10},"source_text":"Sârbu (2017), p. 10","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-020","unit":1,"type":"capcana","front":"Manualul numește regiunile WI–WIV „semiplane”. Ce sunt ele, strict geometric?","back":"Cadrane: OY și OZ împart planul W în patru regiuni, nu în două semiplane.","source":{"kind":"curs_extins","pdf_page":10},"source_text":"Curs universitar extins, p. PDF 10","tags":["U01","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U01-021","unit":1,"type":"definitie","front":"Ce este proiecția unui punct?","back":"O imagine a punctului pe planul de proiecție.","source":{"kind":"sarbu","page":10},"source_text":"Sârbu (2017), p. 10","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-022","unit":1,"type":"definitie","front":"Care sunt proiecțiile punctului N pe cele trei plane și cum se notează?","back":"n = proiecția orizontală (pe H)\nn′ = proiecția verticală (pe V)\nn″ = proiecția laterală (pe W)","source":{"kind":"sarbu","page":10},"source_text":"Sârbu (2017), p. 10","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-023","unit":1,"type":"definitie","front":"Cu ce fel de litere se notează proiecțiile unui punct?","back":"Cu litere mici (punctul din spațiu cu majusculă: N → n, n′, n″).","source":{"kind":"sarbu","page":11},"source_text":"Sârbu (2017), p. 11","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-024","unit":1,"type":"definitie","front":"Ce este axonometria, după definiția din manual?","back":"Reprezentarea unui element în spațiu (punct, dreaptă, plan).","source":{"kind":"sarbu","page":12},"source_text":"Sârbu (2017), p. 12","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-025","unit":1,"type":"explicativ","front":"Ce arată, în sens tehnic, o axonometrie?","back":"Într-o singură imagine plană, proiecția paralelă a obiectului împreună cu triedrul de referință, cu cele trei direcții de coordonate vizibile. Poate fi ortogonală sau oblică.","source":{"kind":"curs_extins","pdf_page":11},"source_text":"Curs universitar extins, p. PDF 11","tags":["U01","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U01-026","unit":1,"type":"formula","front":"Pentru N = (x, y, z), care sunt coordonatele proiecțiilor n, n′, n″?","back":"n = (x, y, 0)\nn′ = (x, 0, z)\nn″ = (0, y, z)","source":{"kind":"curs_extins","pdf_page":10},"source_text":"Curs universitar extins, p. PDF 10","tags":["U01","tip::formula","sursa::Curs_extins"]},{"id":"GD-U01-027","unit":1,"type":"capcana","front":"Poate o singură proiecție să determine un punct din spațiu?","back":"Nu. De exemplu (1,2,3) și (1,2,8) au aceeași proiecție pe H. Două proiecții pe plane distincte, neparalele, determină punctul.","source":{"kind":"curs_extins","pdf_page":10},"source_text":"Curs universitar extins, p. PDF 10","tags":["U01","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U01-028","unit":1,"type":"formula","front":"Cum se compară lungimea proiecției pe H a unui segment cu lungimea lui reală?","back":"L_H = √(Δx² + Δy²) ≤ L = √(Δx² + Δy² + Δz²)\nEgalitate doar dacă Δz = 0, adică segmentul este paralel cu H.","source":{"kind":"curs_extins","pdf_page":9},"source_text":"Curs universitar extins, p. PDF 9","tags":["U01","tip::formula","sursa::Curs_extins"]},{"id":"GD-U01-029","unit":1,"type":"explicativ","front":"Ce păstrează proiecția paralelă pe o dreaptă (nedegenerată) și ce nu păstrează?","back":"Păstrează apartenența și raportul în care un punct împarte segmentul (ac/cb = AC/CB). Nu păstrează, în general, lungimile.","source":{"kind":"curs_extins","pdf_page":10},"source_text":"Curs universitar extins, p. PDF 10","tags":["U01","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U01-030","unit":1,"type":"capcana","front":"„Proiecție ortogonală” înseamnă automat adevărată mărime?","back":"Nu. Un segment apare în adevărată mărime pe un plan doar dacă este paralel cu acel plan; altfel apare prescurtat.","source":{"kind":"curs_extins","pdf_page":11},"source_text":"Curs universitar extins, p. PDF 11","tags":["U01","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U01-031","unit":1,"type":"definitie","front":"Ce trebuie reținut din Unitatea 1, conform manualului?","back":"Reprezentarea oricărui element pornește de la sistemul de referință; un punct din spațiu se proiectează ortogonal pe cele trei plane de proiecție.","source":{"kind":"sarbu","page":11},"source_text":"Sârbu (2017), p. 11","tags":["U01","tip::definitie","sursa::Sarbu"]},{"id":"GD-U01-032","unit":1,"type":"lucrare","front":"Lucrarea de verificare nr. 1: ce cerințe are și cu ce punctaj?","back":"1. Din ce este format sistemul de referință? (2 p)\n2. Semiplanele de proiecție și cum au fost obținute (5 p)\n3. Proiecțiile unui punct pe cele trei plane (3 p)","source":{"kind":"sarbu","page":13},"source_text":"Sârbu (2017), p. 13","tags":["U01","tip::lucrare","sursa::Sarbu","lucrare::L01"]},{"id":"GD-U02-001","unit":2,"type":"definitie","front":"Cum se obține convenția de reprezentare în spațiu (diedrele)?","back":"Planele H și V se prelungesc nelimitat în toate sensurile, de o parte și de alta a liniei de pământ; spațiul apare împărțit în patru regiuni numite diedre, notate I, II, III, IV.","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-002","unit":2,"type":"definitie","front":"În ce sens se numerotează diedrele?","back":"În sens opus acelor de ceasornic.","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-003","unit":2,"type":"definitie","front":"Ce semne au axele în cele patru diedre (formularea manualului)?","back":"D I (+X, +Y, +Z)\nD II (+X, −Y, +Z)\nD III (+X, −Y, −Z)\nD IV (+X, +Y, −Z)","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-004","unit":2,"type":"recunoastere","front":"Un punct are y > 0 și z > 0. În ce diedru se află?","back":"Diedrul I (în fața lui V, deasupra lui H).","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-005","unit":2,"type":"recunoastere","front":"Un punct are y < 0 și z > 0. În ce diedru se află?","back":"Diedrul II (în spatele lui V, deasupra lui H).","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-006","unit":2,"type":"recunoastere","front":"Un punct are y < 0 și z < 0. În ce diedru se află?","back":"Diedrul III (în spatele lui V, sub H).","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-007","unit":2,"type":"recunoastere","front":"Un punct are y > 0 și z < 0. În ce diedru se află?","back":"Diedrul IV (în fața lui V, sub H).","source":{"kind":"sarbu","page":14},"source_text":"Sârbu (2017), p. 14","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-008","unit":2,"type":"capcana","front":"Abscisa x influențează diedrul în care se află un punct?","back":"Nu. Diedrul depinde doar de semnele depărtării y și cotei z. „+X” din tabelul manualului este doar orientarea aleasă pentru figuri.","source":{"kind":"curs_extins","pdf_page":16},"source_text":"Curs universitar extins, p. PDF 16","tags":["U02","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U02-009","unit":2,"type":"definitie","front":"Ce se numește epură?","back":"Operația prin care cele trei plane de proiecție H, V și W devin coplanare. Prin extensie, și desenul plan rezultat.","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-010","unit":2,"type":"procedeu","front":"Cum se rotește planul H pentru a obține epura?","back":"În jurul axei OX, în sensul acelor de ceasornic, până se suprapune peste planul V.","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U02-011","unit":2,"type":"procedeu","front":"După rotirea lui H, peste ce semiplane ale lui V ajung HA și HP?","back":"Semiplanul HA se suprapune peste VI, iar HP peste VS.","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U02-012","unit":2,"type":"procedeu","front":"Cum se rotește planul W pentru a obține epura?","back":"În jurul axei OZ, în sens opus acelor de ceasornic.","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U02-013","unit":2,"type":"definitie","front":"De ce axa OY apare în epură în două poziții?","back":"Pentru că a fost rotită o dată cu planul H (în jurul lui OX) și o dată cu planul W (în jurul lui OZ). Pozițiile se notează OY și OȲ.","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-014","unit":2,"type":"definitie","front":"Unde se măsoară în epură depărtările și cotele, după semn?","back":"Depărtările pozitive sub OX, cele negative deasupra.\nCotele invers: pozitive deasupra OX, negative sub OX.","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-015","unit":2,"type":"recunoastere","front":"În epură: n este sub OX, iar n′ este deasupra OX. În ce diedru e punctul?","back":"Diedrul I (y > 0, z > 0).","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-016","unit":2,"type":"recunoastere","front":"În epură: n și n′ sunt ambele deasupra OX. În ce diedru e punctul?","back":"Diedrul II (y < 0 → n deasupra; z > 0 → n′ deasupra).","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-017","unit":2,"type":"recunoastere","front":"În epură: n este deasupra OX, iar n′ este sub OX. În ce diedru e punctul?","back":"Diedrul III (y < 0, z < 0).","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-018","unit":2,"type":"recunoastere","front":"În epură: n și n′ sunt ambele sub OX. În ce diedru e punctul?","back":"Diedrul IV (y > 0 → n sub; z < 0 → n′ sub).","source":{"kind":"sarbu","page":15},"source_text":"Sârbu (2017), p. 15","tags":["U02","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U02-019","unit":2,"type":"definitie","front":"Ce se numește coordonată a unui punct?","back":"Mărimea distanței de la punct la un plan de proiecție. Coordonatele se măsoară în aceeași unitate, pornind din originea O.","source":{"kind":"sarbu","page":16},"source_text":"Sârbu (2017), p. 16","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-020","unit":2,"type":"definitie","front":"În ce ordine se notează coordonatele punctului N?","back":"Abscisa nx, depărtarea ny, cota nz: N(x; y; z).","source":{"kind":"sarbu","page":16},"source_text":"Sârbu (2017), p. 16","tags":["U02","tip::definitie","sursa::Sarbu"]},{"id":"GD-U02-021","unit":2,"type":"explicativ","front":"Care e diferența dintre o coordonată și o distanță?","back":"Coordonata are semn, distanța nu. „Depărtarea este y = −1” înseamnă că proiecția n este la distanța 1 față de OX, deasupra axei.","source":{"kind":"curs_extins","pdf_page":22},"source_text":"Curs universitar extins, p. PDF 22","tags":["U02","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U02-022","unit":2,"type":"definitie","front":"În convenția cursului, în ce parte a lui O se desenează abscisele pozitive?","back":"Spre stânga originii O, pe axa OX.","source":{"kind":"curs_extins","pdf_page":18},"source_text":"Curs universitar extins, p. PDF 18","tags":["U02","tip::definitie","sursa::Curs_extins"]},{"id":"GD-U02-023","unit":2,"type":"definitie","front":"Ce este linia de ordine?","back":"Perpendiculara pe OX pe care se află perechea de proiecții n și n′ ale aceluiași punct (au aceeași abscisă).","source":{"kind":"curs_extins","pdf_page":22},"source_text":"Curs universitar extins, p. PDF 22","tags":["U02","tip::definitie","sursa::Curs_extins"]},{"id":"GD-U02-024","unit":2,"type":"procedeu","front":"Unde se așază proiecția laterală n″ în epură?","back":"Pe orizontala dusă prin n′ (aceeași cotă), la distanța |y| față de OZ: la dreapta lui OZ pentru y > 0, la stânga pentru y < 0.","source":{"kind":"curs_extins","pdf_page":16},"source_text":"Curs universitar extins, p. PDF 16","tags":["U02","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U02-025","unit":2,"type":"procedeu","front":"Cum se transferă depărtarea din H pe W în epură?","back":"Cu un arc de cerc cu centrul în O (sau cu o dreaptă auxiliară la 45°), de pe axa OY rabătută cu H pe axa OȲ rabătută cu W.","source":{"kind":"curs_extins","pdf_page":16},"source_text":"Curs universitar extins, p. PDF 16","tags":["U02","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U02-026","unit":2,"type":"recunoastere","front":"Un punct se află în planul H. Ce observi în epură?","back":"z = 0, deci proiecția verticală n′ este pe OX (iar n coincide cu punctul).","source":{"kind":"curs_extins","pdf_page":17},"source_text":"Curs universitar extins, p. PDF 17","tags":["U02","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U02-027","unit":2,"type":"recunoastere","front":"Un punct se află în planul V. Ce observi în epură?","back":"y = 0, deci proiecția orizontală n este pe OX (iar n′ coincide cu punctul).","source":{"kind":"curs_extins","pdf_page":17},"source_text":"Curs universitar extins, p. PDF 17","tags":["U02","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U02-028","unit":2,"type":"capcana","front":"Un punct se află pe axa OX. Unde este proiecția lui n″?","back":"În originea O. Pentru N=(x;0;0), n=n′=N pe OX, iar n″=O. Dacă x=0, atunci N=O și toate cele trei proiecții coincid cu N.","source":{"kind":"curs_extins","pdf_page":17},"source_text":"Curs universitar extins, p. PDF 17","tags":["U02","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U02-029","unit":2,"type":"recunoastere","front":"Ce condiție îndeplinește un punct din primul plan bisector (I–III) și cum arată în epură?","back":"z = y (cu același semn). În epură, n și n′ sunt simetrice față de OX.","source":{"kind":"curs_extins","pdf_page":19},"source_text":"Curs universitar extins, p. PDF 19","tags":["U02","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U02-030","unit":2,"type":"recunoastere","front":"Ce condiție îndeplinește un punct din al doilea plan bisector (II–IV) și cum arată în epură?","back":"z = −y. În epură, n și n′ se suprapun.","source":{"kind":"curs_extins","pdf_page":19},"source_text":"Curs universitar extins, p. PDF 19","tags":["U02","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U02-031","unit":2,"type":"capcana","front":"Este suficient |y| = |z| pentru a spune în ce bisector e un punct?","back":"Nu. |y|=|z| reunește ambele bisectoare: z=y pentru primul, z=−y pentru al doilea. Dacă y=z=0, punctul se află pe OX și aparține ambelor plane bisectoare; semnele nu mai separă cazurile.","source":{"kind":"curs_extins","pdf_page":20},"source_text":"Curs universitar extins, p. PDF 20","tags":["U02","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U02-032","unit":2,"type":"formula","front":"Cum se modifică coordonatele la simetria față de H, față de V și față de OX?","back":"față de H: (x, y, −z)\nfață de V: (x, −y, z)\nfață de OX: (x, −y, −z)","source":{"kind":"curs_extins","pdf_page":17},"source_text":"Curs universitar extins, p. PDF 17","tags":["U02","tip::formula","sursa::Curs_extins"]},{"id":"GD-U02-033","unit":2,"type":"formula","front":"Cum se modifică coordonatele la simetria față de planele bisectoare?","back":"față de primul bisector (z = y): (x, z, y), schimbi y cu z\nfață de al doilea (z = −y): (x, −z, −y), schimbi și inversezi","source":{"kind":"curs_extins","pdf_page":17},"source_text":"Curs universitar extins, p. PDF 17","tags":["U02","tip::formula","sursa::Curs_extins"]},{"id":"GD-U02-034","unit":2,"type":"explicativ","front":"Cum verifici rapid o simetrie calculată?","back":"O aplici de două ori: trebuie să revii exact la punctul inițial (reflexia este involutivă).","source":{"kind":"curs_extins","pdf_page":17},"source_text":"Curs universitar extins, p. PDF 17","tags":["U02","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U02-035","unit":2,"type":"capcana","front":"Dacă n și n′ coincid în epură, înseamnă că proiecțiile sunt aceeași în spațiu?","back":"În general, nu: se suprapun imaginile după rabatere, deși proiecțiile sunt pe H și V. Excepție: pentru un punct pe OX, y=z=0 și proiecțiile spațiale n și n′ coincid cu N. Punctul rămâne determinat de x, y, z.","source":{"kind":"curs_extins","pdf_page":20},"source_text":"Curs universitar extins, p. PDF 20","tags":["U02","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U02-036","unit":2,"type":"lucrare","front":"Lucrarea de verificare nr. 2: ce cerințe are și cu ce punctaj?","back":"1. Convenția de reprezentare în spațiu și semnele axelor în cele patru diedre (4 p)\n2. Cum se obține convenția de reprezentare în epură (4 p)\n3. Coordonatele unui punct și ordinea lor (2 p)","source":{"kind":"sarbu","page":18},"source_text":"Sârbu (2017), p. 18","tags":["U02","tip::lucrare","sursa::Sarbu","lucrare::L02"]},{"id":"GD-U03-001","unit":3,"type":"definitie","front":"Prin ce este determinată o dreaptă?","back":"Prin două puncte sau prin un punct și o direcție dată.","source":{"kind":"sarbu","page":19},"source_text":"Sârbu (2017), p. 19","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-002","unit":3,"type":"definitie","front":"Cum se notează proiecțiile dreptei D pe H, V și W?","back":"d pe H, d′ pe V, d″ pe W.","source":{"kind":"sarbu","page":20},"source_text":"Sârbu (2017), p. 20","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-003","unit":3,"type":"definitie","front":"Ce este urma orizontală a unei drepte și cum se notează?","back":"Punctul în care dreapta D înțeapă planul H; se notează prin proiecțiile h, h′.","source":{"kind":"sarbu","page":20},"source_text":"Sârbu (2017), p. 20","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-004","unit":3,"type":"definitie","front":"Unde se află proiecțiile h și h′ ale urmei orizontale?","back":"h coincide cu punctul (care este în H); h′ este pe linia de pământ OX, cota fiind zero.","source":{"kind":"sarbu","page":20},"source_text":"Sârbu (2017), p. 20","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-005","unit":3,"type":"definitie","front":"Ce este urma verticală a unei drepte și unde se află proiecțiile ei?","back":"Punctul în care D înțeapă planul V; se notează v, v′. v′ coincide cu punctul, iar v este pe linia de pământ (depărtarea zero).","source":{"kind":"sarbu","page":20},"source_text":"Sârbu (2017), p. 20","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-006","unit":3,"type":"definitie","front":"Ce este urma laterală a unei drepte?","back":"Punctul w, w″ în care D înțeapă planul lateral W. Proiecțiile ei orizontală și verticală sunt, în epură, pe verticala prin O (manualul: „pe axa secundară OZ”); w″ se află pe W.","source":{"kind":"sarbu","page":20},"source_text":"Sârbu (2017), p. 20","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-007","unit":3,"type":"definitie","front":"Care sunt urmele unei drepte?","back":"Urma orizontală (pe H), urma verticală (pe V) și urma laterală (pe W).","source":{"kind":"sarbu","page":26},"source_text":"Sârbu (2017), p. 26","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-008","unit":3,"type":"procedeu","front":"Cum construiești grafic urma orizontală, fără calcule?","back":"Prelungești d′ până intersectează OX → h′. Prin h′ duci linia de ordine; unde taie d obții h.","source":{"kind":"curs_extins","pdf_page":24},"source_text":"Curs universitar extins, p. PDF 24","tags":["U03","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U03-009","unit":3,"type":"procedeu","front":"Cum construiești grafic urma verticală, fără calcule?","back":"Prelungești d până intersectează OX → v. Prin v duci linia de ordine; unde taie d′ obții v′.","source":{"kind":"curs_extins","pdf_page":24},"source_text":"Curs universitar extins, p. PDF 24","tags":["U03","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U03-010","unit":3,"type":"formula","front":"Cum calculezi parametrul urmelor pentru D(t) = M + t·(Δx, Δy, Δz)?","back":"H (z = 0): t_H = −z_M/Δz\nV (y = 0): t_V = −y_M/Δy\nW (x = 0): t_W = −x_M/Δx\nUrma = D(t) pentru valoarea găsită.","source":{"kind":"curs_extins","pdf_page":24},"source_text":"Curs universitar extins, p. PDF 24","tags":["U03","tip::formula","sursa::Curs_extins"]},{"id":"GD-U03-011","unit":3,"type":"capcana","front":"La calculul urmei H, Δz = 0. Ce concluzie tragi?","back":"Nu împarți la zero. Dacă z_M ≠ 0, dreapta e strict paralelă cu H și nu are urmă H. Dacă z_M = 0, dreapta e conținută în H (fără urmă unică).","source":{"kind":"curs_extins","pdf_page":24},"source_text":"Curs universitar extins, p. PDF 24","tags":["U03","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U03-012","unit":3,"type":"definitie","front":"Care sunt criteriile de clasificare a dreptelor particulare?","back":"Dreptele pot fi paralele sau perpendiculare cu planele de proiecție.","source":{"kind":"sarbu","page":21},"source_text":"Sârbu (2017), p. 21","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-013","unit":3,"type":"definitie","front":"Care sunt dreptele în poziții particulare față de planele de proiecție?","back":"Orizontala (de nivel), frontala (de front), fronto-orizontala, verticala și dreapta de capăt.","source":{"kind":"sarbu","page":26},"source_text":"Sârbu (2017), p. 26","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-014","unit":3,"type":"definitie","front":"Ce este orizontala (dreapta de nivel)?","back":"Dreapta paralelă cu planul H.","source":{"kind":"sarbu","page":21},"source_text":"Sârbu (2017), p. 21","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-015","unit":3,"type":"definitie","front":"Ce caracteristici are orizontala (dreapta de nivel)?","back":"Toate punctele au aceeași cotă; proiecția verticală d′ este paralelă cu OX; dreapta se proiectează în adevărată mărime pe H.","source":{"kind":"sarbu","page":21},"source_text":"Sârbu (2017), p. 21","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-016","unit":3,"type":"definitie","front":"Ce este frontala (dreapta de front) și ce caracteristici are?","back":"Dreapta paralelă cu planul V. Toate punctele au aceeași depărtare; proiecția orizontală d este paralelă cu OX; apare în adevărată mărime pe V.","source":{"kind":"sarbu","page":22},"source_text":"Sârbu (2017), p. 22","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-017","unit":3,"type":"definitie","front":"Ce este fronto-orizontala și ce caracteristici are?","back":"Dreapta paralelă simultan cu V și cu H. Ambele proiecții d și d′ sunt paralele cu OX; apare în adevărată mărime pe ambele plane: MN = mn = m′n′.","source":{"kind":"sarbu","page":22},"source_text":"Sârbu (2017), p. 22","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-018","unit":3,"type":"definitie","front":"Ce este verticala?","back":"Dreapta perpendiculară pe planul H și, implicit, paralelă cu planul V.","source":{"kind":"sarbu","page":23},"source_text":"Sârbu (2017), p. 23","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-019","unit":3,"type":"definitie","front":"Ce caracteristici are o verticală față de planele H, V și W?","back":"Proiecția d pe H se reduce la un punct, care este chiar urma H. Proiecția d′ pe V este perpendiculară pe OX; orice segment vertical apare în adevărată mărime pe V și W. Dacă y≠0, dreapta nu are urmă V; dacă y=0, este conținută în V (fără urmă V unică).","source":{"kind":"sarbu","page":23},"source_text":"Sârbu (2017), p. 23","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-020","unit":3,"type":"definitie","front":"Ce este dreapta de capăt?","back":"Dreapta perpendiculară pe planul V și, implicit, paralelă cu planul H.","source":{"kind":"sarbu","page":23},"source_text":"Sârbu (2017), p. 23","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-021","unit":3,"type":"definitie","front":"Ce caracteristici are dreapta de capăt?","back":"Proiecția d′ pe V se reduce la un punct, care este chiar urma V. Proiecția d pe H este perpendiculară pe OX; orice segment apare în adevărată mărime pe H și W. Dacă z≠0, dreapta nu are urmă H; dacă z=0, este conținută în H (fără urmă H unică).","source":{"kind":"sarbu","page":23},"source_text":"Sârbu (2017), p. 23","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-022","unit":3,"type":"recunoastere","front":"În epură: d′ este paralelă cu OX, iar d este oblică. Ce dreaptă este?","back":"Orizontală (dreaptă de nivel); adevărata mărime se citește pe H.","source":{"kind":"sarbu","page":21},"source_text":"Sârbu (2017), p. 21","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-023","unit":3,"type":"recunoastere","front":"În epură: d este paralelă cu OX, iar d′ este oblică. Ce dreaptă este?","back":"Frontală (dreaptă de front); adevărata mărime se citește pe V.","source":{"kind":"sarbu","page":22},"source_text":"Sârbu (2017), p. 22","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-024","unit":3,"type":"recunoastere","front":"În epură: d și d′ sunt ambele paralele cu OX. Ce dreaptă este?","back":"Fronto-orizontală; adevărata mărime apare pe H și pe V.","source":{"kind":"sarbu","page":22},"source_text":"Sârbu (2017), p. 22","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-025","unit":3,"type":"recunoastere","front":"În epură: proiecția d pe H este un punct. Ce dreaptă este?","back":"Verticală (perpendiculară pe H); adevărata mărime pe V și W.","source":{"kind":"sarbu","page":23},"source_text":"Sârbu (2017), p. 23","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-026","unit":3,"type":"recunoastere","front":"În epură: proiecția d′ pe V este un punct. Ce dreaptă este?","back":"Dreaptă de capăt (perpendiculară pe V); adevărata mărime pe H și W.","source":{"kind":"sarbu","page":23},"source_text":"Sârbu (2017), p. 23","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-027","unit":3,"type":"formula","front":"Cum recunoști dreptele particulare după vectorul director u = (ux, uy, uz)?","back":"orizontală: uz = 0\nfrontală: uy = 0\nfronto-orizontală: uy = uz = 0\nverticală: ux = uy = 0\nde capăt: ux = uz = 0","source":{"kind":"curs_extins","pdf_page":30},"source_text":"Curs universitar extins, p. PDF 30","tags":["U03","tip::formula","sursa::Curs_extins"]},{"id":"GD-U03-028","unit":3,"type":"capcana","front":"Ce urme are o fronto-orizontală (care nu e conținută în H sau V)?","back":"Nu are urme pe H și pe V; are o singură urmă finită, pe W (pentru că ux ≠ 0).","source":{"kind":"curs_extins","pdf_page":32},"source_text":"Curs universitar extins, p. PDF 32","tags":["U03","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U03-029","unit":3,"type":"formula","front":"Care sunt formulele pentru lungimea reală și lungimile proiecțiilor segmentului MN?","back":"MN = √(Δx² + Δy² + Δz²)\nmn = √(Δx² + Δy²)\nm′n′ = √(Δx² + Δz²)\nm″n″ = √(Δy² + Δz²)\nFiecare proiecție ≤ MN.","source":{"kind":"curs_extins","pdf_page":32},"source_text":"Curs universitar extins, p. PDF 32","tags":["U03","tip::formula","sursa::Curs_extins"]},{"id":"GD-U03-030","unit":3,"type":"definitie","front":"Care sunt pozițiile relative a două drepte din spațiu?","back":"Coplanare: paralele sau concurente.\nNecoplanare (drepte oarecare): nu sunt concurente și sunt în plane diferite.","source":{"kind":"sarbu","page":24},"source_text":"Sârbu (2017), p. 24","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-031","unit":3,"type":"definitie","front":"Ce rezultă din paralelismul a două drepte spațiale în epură?","back":"Proiecțiile de același nume sunt paralele ori pot coincide sau degenera. Reciproca nu este automată: la drepte de profil verificăm și W sau vectorii directori.","source":{"kind":"sarbu","page":24},"source_text":"Sârbu (2017), p. 24","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-032","unit":3,"type":"definitie","front":"Ce condiție grafică trebuie verificată pentru două drepte concurente?","back":"Proiecțiile punctului comun k pe H și k′ pe V sunt pe aceeași linie de ordine. Pentru reciproca acestui criteriu este necesar ca proiecțiile să aibă intersecții unice și direcțiile ambelor drepte să aibă componenta x nenulă; altfel verificăm W/analitic.","source":{"kind":"sarbu","page":24},"source_text":"Sârbu (2017), p. 24","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-033","unit":3,"type":"definitie","front":"Ce sunt dreptele oarecare una față de alta?","back":"Două drepte necoplanare: nu sunt nici paralele, nici concurente în spațiu. Proiecțiile singure pot avea intersecții aparente; comparăm punctele spațiale și direcțiile.","source":{"kind":"sarbu","page":25},"source_text":"Sârbu (2017), p. 25","tags":["U03","tip::definitie","sursa::Sarbu"]},{"id":"GD-U03-034","unit":3,"type":"recunoastere","front":"Două drepte au proiecțiile pe H paralele, dar pe V concurente. Ce sunt?","back":"Drepte oarecare (necoplanare): nici paralele, nici concurente (manualul, Fig. 3.4.4).","source":{"kind":"sarbu","page":25},"source_text":"Sârbu (2017), p. 25","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-035","unit":3,"type":"recunoastere","front":"Proiecțiile se intersectează și pe H, și pe V, dar k₁ și k′₂ nu sunt pe aceeași linie de ordine. Ce concluzie tragi?","back":"Dreptele nu sunt concurente: k₁ și k′₂ sunt doar puncte de concurență aparente (manualul, Fig. 3.4.5).","source":{"kind":"sarbu","page":25},"source_text":"Sârbu (2017), p. 25","tags":["U03","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U03-036","unit":3,"type":"capcana","front":"De ce o dreaptă de profil poate păcăli criteriile de concurență și paralelism citite doar pe H și V?","back":"Are x constant, deci d și d′ sunt perpendiculare pe OX, pe aceeași linie de ordine; abscisa nu mai identifică un singur punct al ei. Concluzia se verifică pe W sau prin coordonate.","source":{"kind":"curs_extins","pdf_page":35},"source_text":"Curs universitar extins, p. PDF 35","tags":["U03","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U03-037","unit":3,"type":"capcana","front":"Când este suficient criteriul „k și k′ pe aceeași linie de ordine” pentru concurență?","back":"Când ambele drepte au componenta x a direcției nenulă și proiecțiile pe H și V au intersecții unice. Altfel (de exemplu la drepte de profil), verifici pe W.","source":{"kind":"curs_extins","pdf_page":34},"source_text":"Curs universitar extins, p. PDF 34","tags":["U03","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U03-038","unit":3,"type":"capcana","front":"„Dreaptă oarecare” are în curs două sensuri. Care sunt?","back":"1. O dreaptă fără poziție particulară față de planele de proiecție.\n2. Două drepte în poziție oarecare una față de alta, adică necoplanare.","source":{"kind":"curs_extins","pdf_page":33},"source_text":"Curs universitar extins, p. PDF 33","tags":["U03","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U03-039","unit":3,"type":"procedeu","front":"Cum afli prin ce diedre trece o dreaptă?","back":"Studiezi semnele lui y(t) și z(t). Urmele V (y = 0) și H (z = 0) sunt frontierele dintre diedre; între ele, diedrul rezultă din perechea de semne.","source":{"kind":"curs_extins","pdf_page":29},"source_text":"Curs universitar extins, p. PDF 29","tags":["U03","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U03-040","unit":3,"type":"lucrare","front":"Lucrarea de verificare nr. 3: ce cerințe are și cu ce punctaj?","back":"1. Reprezentarea unei drepte în axonometrie și în epură (3 p)\n2. O dreaptă particulară: axonometrie, epură, caracteristici (4 p)\n3. Drepte paralele, concurente sau oarecare (3 p)","source":{"kind":"sarbu","page":27},"source_text":"Sârbu (2017), p. 27","tags":["U03","tip::lucrare","sursa::Sarbu","lucrare::L03"]},{"id":"GD-U04-001","unit":4,"type":"definitie","front":"Prin ce elemente poate fi determinat (reprezentat) un plan?","back":"• trei puncte necoliniare\n• o dreaptă și un punct exterior ei\n• două drepte concurente\n• două drepte paralele","source":{"kind":"sarbu","page":28},"source_text":"Sârbu (2017), p. 28","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-002","unit":4,"type":"definitie","front":"Ce sunt urmele unui plan și cum se notează?","back":"Dreptele după care planul P intersectează planele H și V: urma orizontală Ph și urma verticală Pv.","source":{"kind":"sarbu","page":28},"source_text":"Sârbu (2017), p. 28","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-003","unit":4,"type":"definitie","front":"Ce este punctul Px al unui plan?","back":"Punctul de concurență al planelor P, H și V, în care se întâlnesc Ph, OX și Pv.","source":{"kind":"sarbu","page":28},"source_text":"Sârbu (2017), p. 28","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-004","unit":4,"type":"definitie","front":"Ce simplificare de notație se face în epură pentru urmele planului?","back":"Nu se mai notează proiecțiile urmelor pe linia OX.","source":{"kind":"sarbu","page":28},"source_text":"Sârbu (2017), p. 28","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-005","unit":4,"type":"definitie","front":"Când poate fi determinată urma laterală a unui plan oarecare?","back":"Când se cunosc urmele lui pe planul orizontal și pe planul vertical.","source":{"kind":"sarbu","page":28},"source_text":"Sârbu (2017), p. 28","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-006","unit":4,"type":"procedeu","front":"Cum se construiește urma laterală Pw cunoscând Ph și Pv?","back":"1. Prelungești Ph și Pv până la W → obții Py și Pz.\n2. Transpui punctul Py (pe OȲ).\n3. Dreapta Py–Pz este urma laterală Pw.","source":{"kind":"sarbu","page":29},"source_text":"Sârbu (2017), p. 29","tags":["U04","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U04-007","unit":4,"type":"definitie","front":"Care sunt criteriile de clasificare a planelor particulare?","back":"Planele pot fi perpendiculare pe planele de proiecție sau paralele cu acestea.","source":{"kind":"sarbu","page":29},"source_text":"Sârbu (2017), p. 29","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-008","unit":4,"type":"definitie","front":"Care sunt planele în poziții particulare față de planele de proiecție?","back":"Planul orizontal (de nivel), planul de front, planul de profil, planul vertical și planul de capăt.","source":{"kind":"sarbu","page":34},"source_text":"Sârbu (2017), p. 34","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-009","unit":4,"type":"definitie","front":"Ce este planul vertical?","back":"Un plan perpendicular pe planul orizontal de proiecție H.","source":{"kind":"sarbu","page":29},"source_text":"Sârbu (2017), p. 29","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-010","unit":4,"type":"definitie","front":"Ce caracteristici are planul vertical?","back":"Orice dreaptă din plan are proiecția orizontală d pe urma Ph; orice figură plană din plan se proiectează pe H după urma Ph.","source":{"kind":"sarbu","page":30},"source_text":"Sârbu (2017), p. 30","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-011","unit":4,"type":"definitie","front":"Ce este planul de capăt?","back":"Un plan perpendicular pe planul vertical de proiecție V.","source":{"kind":"sarbu","page":30},"source_text":"Sârbu (2017), p. 30","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-012","unit":4,"type":"definitie","front":"Ce caracteristici are planul de capăt?","back":"Urma orizontală Ph este perpendiculară pe linia de pământ; orice dreaptă din plan are d′ pe urma Pv; orice figură din plan se proiectează pe V chiar pe Pv.","source":{"kind":"sarbu","page":30},"source_text":"Sârbu (2017), p. 30","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-013","unit":4,"type":"definitie","front":"Ce este planul de profil?","back":"Un plan perpendicular pe ambele plane de proiecție, H și V.","source":{"kind":"sarbu","page":30},"source_text":"Sârbu (2017), p. 30","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-014","unit":4,"type":"definitie","front":"Ce caracteristici are planul de profil?","back":"Este paralel cu W; orice element din el apare în adevărată mărime pe W; urmele Ph și Pv sunt în prelungire și perpendiculare pe OX.","source":{"kind":"sarbu","page":31},"source_text":"Sârbu (2017), p. 31","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-015","unit":4,"type":"definitie","front":"Ce este planul orizontal (de nivel)?","back":"Un plan paralel cu planul orizontal de proiecție H.","source":{"kind":"sarbu","page":31},"source_text":"Sârbu (2017), p. 31","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-016","unit":4,"type":"definitie","front":"Ce caracteristici are planul de nivel?","back":"Nu are urmă orizontală (e paralel cu H); urma verticală Pv este paralelă cu OX; orice figură din el apare în adevărată mărime pe H; este un plan de capăt în poziție particulară.","source":{"kind":"sarbu","page":31},"source_text":"Sârbu (2017), p. 31","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-017","unit":4,"type":"definitie","front":"Ce este planul de front (frontal)?","back":"Un plan paralel cu planul V și perpendicular pe H.","source":{"kind":"sarbu","page":31},"source_text":"Sârbu (2017), p. 31","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-018","unit":4,"type":"definitie","front":"Ce caracteristici are planul de front?","back":"Are o singură urmă (în sistemul H–V), Ph, paralelă cu OX; orice figură din el apare în adevărată mărime pe V; este un plan vertical în poziție particulară.","source":{"kind":"sarbu","page":32},"source_text":"Sârbu (2017), p. 32","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-019","unit":4,"type":"capcana","front":"Planul de front are „o singură urmă”. Este adevărat și în sistemul H–V–W?","back":"Nu complet: în sistemul H–V are doar Ph, dar pe W are și urma Pw. Analog, planul de nivel are urme pe V și W.","source":{"kind":"curs_extins","pdf_page":44},"source_text":"Curs universitar extins, p. PDF 44","tags":["U04","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U04-020","unit":4,"type":"recunoastere","front":"În epură: Ph este perpendiculară pe OX, Pv este oblică. Ce plan este?","back":"Plan de capăt (perpendicular pe V).","source":{"kind":"sarbu","page":30},"source_text":"Sârbu (2017), p. 30","tags":["U04","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U04-021","unit":4,"type":"recunoastere","front":"În epură: Pv este perpendiculară pe OX, Ph este oblică. Ce plan este?","back":"Plan vertical (perpendicular pe H): ecuația lui nu conține z, deci Pv are x constant.","source":{"kind":"curs_extins","pdf_page":44},"source_text":"Curs universitar extins, p. PDF 44","tags":["U04","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U04-022","unit":4,"type":"recunoastere","front":"În epură: Ph și Pv sunt în prelungire, ambele perpendiculare pe OX. Ce plan este?","back":"Plan de profil (paralel cu W).","source":{"kind":"sarbu","page":31},"source_text":"Sârbu (2017), p. 31","tags":["U04","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U04-023","unit":4,"type":"recunoastere","front":"În epură planul are doar urma Pv, paralelă cu OX. Ce plan este?","back":"Plan de nivel (orizontal), paralel cu H.","source":{"kind":"sarbu","page":31},"source_text":"Sârbu (2017), p. 31","tags":["U04","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U04-024","unit":4,"type":"recunoastere","front":"În epură planul are doar urma Ph, paralelă cu OX. Ce plan este?","back":"Plan de front, paralel cu V.","source":{"kind":"sarbu","page":32},"source_text":"Sârbu (2017), p. 32","tags":["U04","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U04-025","unit":4,"type":"formula","front":"Cum arată ecuațiile planelor particulare?","back":"vertical: Ax + By + D = 0 (fără z)\nde capăt: Ax + Cz + D = 0 (fără y)\nde nivel: z = c\nde front: y = c\nde profil: x = c","source":{"kind":"curs_extins","pdf_page":44},"source_text":"Curs universitar extins, p. PDF 44","tags":["U04","tip::formula","sursa::Curs_extins"]},{"id":"GD-U04-026","unit":4,"type":"formula","front":"Cum obții ecuațiile urmelor din P: Ax + By + Cz + D = 0?","back":"Ph: Ax + By + D = 0 (z = 0)\nPv: Ax + Cz + D = 0 (y = 0)\nPw: By + Cz + D = 0 (x = 0)","source":{"kind":"curs_extins","pdf_page":43},"source_text":"Curs universitar extins, p. PDF 43","tags":["U04","tip::formula","sursa::Curs_extins"]},{"id":"GD-U04-027","unit":4,"type":"capcana","front":"Există întotdeauna punctul Px în care se întâlnesc urmele pe OX?","back":"Nu. Dacă planul e paralel cu OX (de ex. y + z = 1), Ph și Pv sunt paralele cu OX, fără punct comun. Dacă planul conține OX (y + z = 0), nu există un punct unic.","source":{"kind":"curs_extins","pdf_page":53},"source_text":"Curs universitar extins, p. PDF 53","tags":["U04","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U04-028","unit":4,"type":"definitie","front":"Care sunt pozițiile relative a două plane?","back":"Paralele sau concurente.","source":{"kind":"sarbu","page":32},"source_text":"Sârbu (2017), p. 32","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-029","unit":4,"type":"definitie","front":"Ce rezultă din paralelismul a două plane în epură?","back":"Pentru două plane distincte și paralele, urmele de același nume, dacă există ca drepte, sunt paralele și distincte; dacă ambele plane sunt strict paralele cu planul de proiecție, ambele urme lipsesc. Reciproca nu este valabilă fără condiții suplimentare (verifică și W când urmele pe H și V sunt paralele cu OX).","source":{"kind":"sarbu","page":33},"source_text":"Sârbu (2017), p. 33","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-030","unit":4,"type":"capcana","front":"Urmele pe H și V a două plane sunt paralele. Sunt sigur planele paralele?","back":"Nu întotdeauna. Când toate urmele sunt paralele cu OX (ex. y + z = 1 și y + 2z = 3), planele se pot intersecta. Verifici și urmele pe W.","source":{"kind":"curs_extins","pdf_page":44},"source_text":"Curs universitar extins, p. PDF 44","tags":["U04","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U04-031","unit":4,"type":"definitie","front":"După ce se intersectează două plane concurente?","back":"După o dreaptă.","source":{"kind":"sarbu","page":33},"source_text":"Sârbu (2017), p. 33","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-032","unit":4,"type":"definitie","front":"Ce poziții poate avea o dreaptă față de un plan oarecare?","back":"Paralelă cu planul sau oarecare față de plan.","source":{"kind":"sarbu","page":33},"source_text":"Sârbu (2017), p. 33","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-033","unit":4,"type":"definitie","front":"Cum distingi o dreaptă strict paralelă cu un plan de una conținută în el?","back":"În ambele cazuri direcția dreptei este paralelă cu o direcție a planului. Dacă un punct al dreptei aparține planului, întreaga dreaptă este conținută în plan; altfel este strict paralelă, fără puncte comune.","source":{"kind":"sarbu","page":33},"source_text":"Sârbu (2017), p. 33","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-034","unit":4,"type":"definitie","front":"Câte plane se pot duce printr-o dreaptă?","back":"O infinitate.","source":{"kind":"sarbu","page":33},"source_text":"Sârbu (2017), p. 33","tags":["U04","tip::definitie","sursa::Sarbu"]},{"id":"GD-U04-035","unit":4,"type":"procedeu","front":"Cum verifici în epură că o dreaptă aparține unui plan?","back":"Dacă dreapta are două urme finite distincte H și V, verifici h pe Ph și v′ pe Pv: două puncte distincte din plan determină o dreaptă inclusă în plan. Dacă urmele coincid pe OX, lipsesc sau nu sunt unice, verifici două puncte distincte ori folosești o construcție auxiliară; simpla apartenență a unei singure urme nu este suficientă.","source":{"kind":"curs_extins","pdf_page":45},"source_text":"Curs universitar extins, p. PDF 45","tags":["U04","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U04-036","unit":4,"type":"procedeu","front":"Cum construiești dreapta de intersecție a două plane P și Q, din urme?","back":"Construiești Hᵢ=Ph∩Qh și Vᵢ=Pv∩Qv. Dacă sunt două puncte finite distincte, le corelezi proiecțiile prin linii de ordine și unești proiecțiile de același nume. Dacă Hᵢ=Vᵢ pe OX ori o urmă lipsește sau nu este unică, obții un al doilea punct printr-un plan auxiliar ori folosești vederea W. Metoda presupune plane distincte neparalele.","source":{"kind":"curs_extins","pdf_page":46},"source_text":"Curs universitar extins, p. PDF 46","tags":["U04","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U04-037","unit":4,"type":"procedeu","front":"Care sunt pașii pentru intersecția dreaptă–plan cu plan auxiliar proiectant?","back":"1. Prin D duci un plan proiectant Q (de ex. Qv = d′).\n2. Construiești I = P ∩ Q din urme.\n3. Pe H: k = d ∩ i.\n4. Linia de ordine din k pe d′ dă k′.\n5. Verifici K pe D și pe P.","source":{"kind":"curs_extins","pdf_page":48},"source_text":"Curs universitar extins, p. PDF 48","tags":["U04","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U04-038","unit":4,"type":"capcana","front":"Dreapta D are direcția paralelă cu planul P (n·u = 0). Ce variante există?","back":"Dacă un punct al lui D verifică ecuația lui P, dreapta este inclusă în plan; dacă nu, este strict paralelă, fără puncte comune.","source":{"kind":"curs_extins","pdf_page":44},"source_text":"Curs universitar extins, p. PDF 44","tags":["U04","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U04-039","unit":4,"type":"lucrare","front":"Lucrarea de verificare nr. 4: ce cerințe are și cu ce punctaj?","back":"1. Intersecția unui plan cu planele de proiecție; urmele planului (3 p)\n2. Un plan particular: axonometrie, epură, caracteristici (5 p)\n3. Poziția relativă a două plane și a unei drepte față de un plan (2 p)","source":{"kind":"sarbu","page":34},"source_text":"Sârbu (2017), p. 34","tags":["U04","tip::lucrare","sursa::Sarbu","lucrare::L04"]},{"id":"GD-U05-001","unit":5,"type":"definitie","front":"De ce figurile nu apar, de regulă, în adevărată mărime în proiecții?","back":"Din cauza pozițiilor oarecare în care se află în spațiu față de planele de proiecție.","source":{"kind":"sarbu","page":36},"source_text":"Sârbu (2017), p. 36","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-002","unit":5,"type":"definitie","front":"Care sunt cele două căi pentru a afla adevărata mărime a unui element?","back":"Fie aduci planul de proiecție într-o poziție particulară (paralel) față de element, fie aduci elementul într-o poziție avantajoasă față de planul de proiecție.","source":{"kind":"sarbu","page":36},"source_text":"Sârbu (2017), p. 36","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-003","unit":5,"type":"definitie","front":"În ce constă metoda schimbării planelor de proiecție?","back":"Obiectul din spațiu și unul din planele de proiecție rămân fixe; se modifică poziția celui de-al doilea plan de proiecție.","source":{"kind":"sarbu","page":36},"source_text":"Sârbu (2017), p. 36","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-004","unit":5,"type":"definitie","front":"La schimbarea planului vertical (pentru un punct), ce rămâne nemodificat?","back":"Poziția punctului în spațiu, planul orizontal, proiecția orizontală a punctului și cota punctului.","source":{"kind":"sarbu","page":36},"source_text":"Sârbu (2017), p. 36","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-005","unit":5,"type":"definitie","front":"La schimbarea planului vertical (pentru un punct), ce se modifică?","back":"Linia de pământ, depărtarea punctului și proiecția verticală.","source":{"kind":"sarbu","page":36},"source_text":"Sârbu (2017), p. 36","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-006","unit":5,"type":"definitie","front":"La schimbarea planului orizontal (pentru un punct), ce rămâne nemodificat?","back":"Poziția punctului în spațiu, planul vertical, proiecția verticală și depărtarea punctului.","source":{"kind":"sarbu","page":37},"source_text":"Sârbu (2017), p. 37","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-007","unit":5,"type":"definitie","front":"La schimbarea planului orizontal (pentru un punct), ce se modifică?","back":"Linia de pământ, cota punctului și proiecția orizontală.","source":{"kind":"sarbu","page":37},"source_text":"Sârbu (2017), p. 37","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-008","unit":5,"type":"procedeu","front":"În ce transformi o dreaptă oarecare prin schimbarea planului vertical?","back":"Într-o frontală (paralelă cu noul plan vertical), care apare în adevărată mărime pe acesta.","source":{"kind":"sarbu","page":37},"source_text":"Sârbu (2017), p. 37","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-009","unit":5,"type":"procedeu","front":"În ce transformi un plan oarecare prin schimbarea planului vertical?","back":"Într-un plan de capăt.","source":{"kind":"sarbu","page":37},"source_text":"Sârbu (2017), p. 37","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-010","unit":5,"type":"procedeu","front":"În ce transformi o dreaptă oarecare prin schimbarea planului orizontal?","back":"Într-o orizontală.","source":{"kind":"sarbu","page":38},"source_text":"Sârbu (2017), p. 38","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-011","unit":5,"type":"procedeu","front":"În ce transformi un plan oarecare prin schimbarea planului orizontal?","back":"Într-un plan vertical.","source":{"kind":"sarbu","page":38},"source_text":"Sârbu (2017), p. 38","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-012","unit":5,"type":"definitie","front":"Pentru ce elemente se poate aplica schimbarea planelor de proiecție?","back":"Pentru un punct, o dreaptă sau un plan.","source":{"kind":"sarbu","page":43},"source_text":"Sârbu (2017), p. 43","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-013","unit":5,"type":"procedeu","front":"Cum afli adevărata mărime a lui MN prin schimbarea planului vertical?","back":"1. Trasezi noua linie de pământ O₁X₁ paralelă cu mn.\n2. Din m și n duci perpendiculare pe O₁X₁.\n3. Reportezi cotele cu semn → m₁′, n₁′.\n4. m₁′n₁′ este adevărata mărime.","source":{"kind":"curs_extins","pdf_page":58},"source_text":"Curs universitar extins, p. PDF 58","tags":["U05","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U05-014","unit":5,"type":"definitie","front":"În ce constă metoda rotației?","back":"În aducerea unei figuri din spațiu într-o poziție particulară față de unul din planele de proiecție, pentru a-i determina adevărata mărime. Rotația se face în jurul unei axe.","source":{"kind":"sarbu","page":38},"source_text":"Sârbu (2017), p. 38","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-015","unit":5,"type":"definitie","front":"Ce tipuri de rotație există și ce axe folosesc?","back":"Rotația de nivel: axa este o verticală (perpendiculară pe H).\nRotația de front: axa este o dreaptă de capăt (perpendiculară pe V).","source":{"kind":"sarbu","page":39},"source_text":"Sârbu (2017), p. 39","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-016","unit":5,"type":"procedeu","front":"Ce rotești pentru a roti o dreaptă?","back":"Este suficient să rotești două puncte ale ei. Axa de rotație poate întâlni sau nu dreapta.","source":{"kind":"sarbu","page":39},"source_text":"Sârbu (2017), p. 39","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-017","unit":5,"type":"procedeu","front":"Ce variante de rotație de nivel a unui plan prezintă manualul?","back":"c1) în jurul unei axe verticale conținute în planul vertical de proiecție [V];\nc2) folosind linia de cea mai mare pantă a planului.","source":{"kind":"sarbu","page":39},"source_text":"Sârbu (2017), p. 39","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-018","unit":5,"type":"definitie","front":"Ce descriu punctele unei figuri în rotația de front și unde apar în adevărată mărime?","back":"Descriu arce de cerc în plane de front. Arcele și unghiul de rotație apar în adevărată mărime pe planul vertical V.","source":{"kind":"sarbu","page":40},"source_text":"Sârbu (2017), p. 40","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-019","unit":5,"type":"explicativ","front":"Ce rămâne neschimbat la rotația de nivel?","back":"Cota fiecărui punct și distanța lui față de axă. Proiecția orizontală se mișcă pe un arc de cerc în jurul axei.","source":{"kind":"curs_extins","pdf_page":60},"source_text":"Curs universitar extins, p. PDF 60","tags":["U05","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U05-020","unit":5,"type":"explicativ","front":"Ce rămâne neschimbat la rotația de front?","back":"Depărtarea fiecărui punct și distanța lui față de axă.","source":{"kind":"curs_extins","pdf_page":60},"source_text":"Curs universitar extins, p. PDF 60","tags":["U05","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U05-021","unit":5,"type":"capcana","front":"Rotești n pe H la rotația de nivel. Ce greșeală frecventă apare la n′?","back":"Lași n′ pe vechea linie de ordine. Corect: n′ se mută pe orizontala cotei neschimbate, la noua abscisă a lui n₁.","source":{"kind":"curs_extins","pdf_page":61},"source_text":"Curs universitar extins, p. PDF 61","tags":["U05","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U05-022","unit":5,"type":"definitie","front":"Ce este metoda rabaterii?","back":"Un caz particular de rotație, prin care se obține în adevărată mărime orice figură sau element cuprins în planul care se rabate.","source":{"kind":"sarbu","page":41},"source_text":"Sârbu (2017), p. 41","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-023","unit":5,"type":"definitie","front":"Ce plane proiectante se folosesc la rabatere în curs?","back":"Planul vertical și planul de capăt.","source":{"kind":"sarbu","page":43},"source_text":"Sârbu (2017), p. 43","tags":["U05","tip::definitie","sursa::Sarbu"]},{"id":"GD-U05-024","unit":5,"type":"procedeu","front":"Pe ce plane se rabate planul vertical, în manual?","back":"Pe H și pe V.","source":{"kind":"sarbu","page":41},"source_text":"Sârbu (2017), p. 41","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-025","unit":5,"type":"procedeu","front":"Pe ce plane se rabate planul de capăt, în manual?","back":"Pe H și pe V.","source":{"kind":"sarbu","page":42},"source_text":"Sârbu (2017), p. 42","tags":["U05","tip::procedeu","sursa::Sarbu"]},{"id":"GD-U05-026","unit":5,"type":"explicativ","front":"Ce rămâne invariant la rabaterea unui punct pe H?","back":"Distanța față de axa de rabatere (urma), deci și lungimile și forma figurii din plan. Cota inițială nu se păstrează.","source":{"kind":"curs_extins","pdf_page":63},"source_text":"Curs universitar extins, p. PDF 63","tags":["U05","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U05-027","unit":5,"type":"procedeu","front":"Cum rabați pe H un punct M dintr-un plan de capăt?","back":"1. Iei cu compasul ρ = |Px m′| de pe Pv (este deja adevărata mărime).\n2. Prin m duci paralela la OX.\n3. Pe ea măsori ρ de la Ph → M₀.\nSensul rabaterii se alege: de partea opusă urmei Ph față de m, ca în Sârbu, Fig. 5.4.3, sau de aceeași parte. Ambele păstrează lungimile reale.","source":{"kind":"curs_extins","pdf_page":62},"source_text":"Curs universitar extins, p. PDF 62","tags":["U05","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U05-028","unit":5,"type":"formula","front":"Care e formula de rabatere pe H pentru planul de capăt z = kx + b?","back":"Pentru k ≠ 0: x₀ = xₕ ± (x − xₕ)√(1 + k²), y₀ = y, unde xₕ = −b/k. Sensul se alege. În Fig. 5.4.3 (Sârbu, p. 42), M₀ este de partea opusă urmei Ph față de m: x₀ = xₕ − (x − xₕ)√(1 + k²). Lungimile reale sunt aceleași. Dacă k=0, planul este de nivel; această definiție a lui xₕ nu se aplică.","source":{"kind":"curs_extins","pdf_page":62},"source_text":"Curs universitar extins, p. PDF 62","tags":["U05","tip::formula","sursa::Curs_extins"]},{"id":"GD-U05-029","unit":5,"type":"capcana","front":"Distanța ρ de la M la axa de rabatere este și abscisa punctului rabătut?","back":"Nu. ρ se măsoară de la urma Ph; abscisa lui M₀ este x_h + ρ (pe partea aleasă), nu ρ.","source":{"kind":"curs_extins","pdf_page":65},"source_text":"Curs universitar extins, p. PDF 65","tags":["U05","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U05-030","unit":5,"type":"capcana","front":"Orice rabatere se face cu 90°?","back":"Nu. 90° doar pentru plan vertical rabătut pe H sau plan de capăt rabătut pe V; altfel unghiul depinde de înclinarea planului.","source":{"kind":"curs_extins","pdf_page":61},"source_text":"Curs universitar extins, p. PDF 61","tags":["U05","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U05-031","unit":5,"type":"explicativ","front":"Ce rămâne fix la fiecare metodă: schimbarea planelor, rotație, rabatere?","back":"Schimbare: obiectul și unul din plane.\nRotație: planele de proiecție (obiectul se mișcă).\nRabatere: axa (urma) de rabatere; planul figurii se rotește în jurul ei.","source":{"kind":"curs_extins","pdf_page":66},"source_text":"Curs universitar extins, p. PDF 66","tags":["U05","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U05-032","unit":5,"type":"capcana","front":"Ai aflat adevărata mărime a unui segment prin două metode și rezultatele diferă. Ce înseamnă?","back":"O eroare de construcție sau de date. Metodele corecte dau aceeași valoare.","source":{"kind":"curs_extins","pdf_page":66},"source_text":"Curs universitar extins, p. PDF 66","tags":["U05","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U05-033","unit":5,"type":"lucrare","front":"Lucrarea de verificare nr. 5: ce cerințe are și cu ce punctaj?","back":"1. În ce constă metoda schimbării planelor de proiecție? (3 p)\n2. Metoda rotației; tipurile rotației de nivel și de front (3 p)\n3. Ce este rabaterea? Ce plane proiectante se folosesc? (4 p)","source":{"kind":"sarbu","page":43},"source_text":"Sârbu (2017), p. 43","tags":["U05","tip::lucrare","sursa::Sarbu","lucrare::L05"]},{"id":"GD-U06-001","unit":6,"type":"definitie","front":"Ce este un poliedru?","back":"Un corp geometric mărginit de fețe plane poligonale; fețele se intersectează după muchii.\nAtenție: manualul scrie „mărginit de două feţe plane”; un poliedru închis are cel puțin patru fețe (tetraedrul).","source":{"kind":"sarbu+curs_extins","page":44},"source_text":"Sârbu (2017), p. 44 + precizare din Cursul extins","tags":["U06","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U06-002","unit":6,"type":"definitie","front":"Ce sunt muchiile unui poliedru?","back":"Intersecțiile fețelor plane; laturile poligoanelor fețelor sunt chiar muchiile.","source":{"kind":"sarbu","page":44},"source_text":"Sârbu (2017), p. 44","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-003","unit":6,"type":"definitie","front":"Ce formează un vârf al poliedrului?","back":"Intersecția a cel puțin trei fețe.","source":{"kind":"sarbu","page":44},"source_text":"Sârbu (2017), p. 44","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-004","unit":6,"type":"definitie","front":"Cum se clasifică poliedrele?","back":"Regulate, semiregulate și neregulate.","source":{"kind":"sarbu","page":48},"source_text":"Sârbu (2017), p. 48","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-005","unit":6,"type":"definitie","front":"Care sunt cele cinci poliedre regulate?","back":"Tetraedrul (4 fețe triunghiuri echilaterale), hexaedrul sau cubul (6 pătrate), octaedrul (8 triunghiuri echilaterale), dodecaedrul (12 pentagoane), icosaedrul (20 triunghiuri echilaterale).","source":{"kind":"sarbu","page":44},"source_text":"Sârbu (2017), p. 44","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-006","unit":6,"type":"recunoastere","front":"Poliedru regulat cu 12 fețe pentagonale?","back":"Dodecaedrul.","source":{"kind":"sarbu","page":44},"source_text":"Sârbu (2017), p. 44","tags":["U06","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U06-007","unit":6,"type":"recunoastere","front":"Poliedru regulat cu 20 de fețe triunghiuri echilaterale?","back":"Icosaedrul.","source":{"kind":"sarbu","page":44},"source_text":"Sârbu (2017), p. 44","tags":["U06","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U06-008","unit":6,"type":"recunoastere","front":"Poliedru regulat cu 8 fețe triunghiuri echilaterale?","back":"Octaedrul.","source":{"kind":"sarbu","page":44},"source_text":"Sârbu (2017), p. 44","tags":["U06","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U06-009","unit":6,"type":"definitie","front":"Ce exemple de poliedre semiregulate dă manualul?","back":"Tetraedrul trunchiat, octaedrul trunchiat, icosaedrul trunchiat, dodecaedrul teșit ș.a.\nAtenție: lista din manual include și „hexaedrul”, dar cubul este poliedru regulat.","source":{"kind":"sarbu+curs_extins","page":45},"source_text":"Sârbu (2017), p. 45 + precizare din Cursul extins","tags":["U06","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U06-010","unit":6,"type":"definitie","front":"Care sunt cele mai des întâlnite poliedre neregulate?","back":"Prisma și piramida.","source":{"kind":"sarbu","page":45},"source_text":"Sârbu (2017), p. 45","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-011","unit":6,"type":"capcana","front":"Prisma și piramida sunt întotdeauna poliedre neregulate?","back":"Nu. Cubul este o prismă și e regulat; tetraedrul regulat este o piramidă.","source":{"kind":"curs_extins","pdf_page":68},"source_text":"Curs universitar extins, p. PDF 68","tags":["U06","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U06-012","unit":6,"type":"definitie","front":"De ce trebuie analizate cu atenție muchiile din interiorul conturului aparent?","back":"Vizibilitatea se decide comparând puncte de pe aceeași proiectantă: pe H, privit din +Z, se vede punctul cu cota mai mare; pe V, privit din +Y, cel cu depărtarea mai mare. Muchiile acoperite se desenează întrerupt, chiar când se proiectează în interiorul conturului aparent.\nManualul (Sârbu 2017, p. 45) formulează: muchiile din interiorul conturului aparent, pe H, sunt vizibile. Regula se aplică figurii din curs. În general, vizibilitatea se decide comparând cotele pe H și depărtările pe V (suport extins).","source":{"kind":"sarbu+curs_extins","page":45},"source_text":"Sârbu (2017), p. 45; suport extins, regula generală de vizibilitate","tags":["U06","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U06-013","unit":6,"type":"capcana","front":"„Toate muchiile din interiorul conturului pe H sunt vizibile” este o regulă generală?","back":"Nu. Vizibilitatea se decide separat pentru fiecare proiecție, comparând adâncimile punctelor care se suprapun (de ex. la o prismă oblică o muchie a bazei de jos poate fi ascunsă pe H).\nManualul (Sârbu 2017, p. 45) formulează: muchiile din interiorul conturului aparent, pe H, sunt vizibile. Regula se aplică figurii din curs. În general, vizibilitatea se decide comparând cotele pe H și depărtările pe V (suport extins).","source":{"kind":"sarbu+curs_extins","pdf_page":68,"page":45},"source_text":"Sârbu (2017), p. 45; suport extins, regula generală de vizibilitate","tags":["U06","tip::capcana","sursa::Sarbu+Curs_extins"]},{"id":"GD-U06-014","unit":6,"type":"procedeu","front":"Cum decizi care dintre două puncte suprapuse este vizibil pe H și pe V?","back":"Pe H (privind din +Z): cel cu cota z mai mare.\nPe V (privind din +Y): cel cu depărtarea y mai mare.","source":{"kind":"curs_extins","pdf_page":68},"source_text":"Curs universitar extins, p. PDF 68","tags":["U06","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U06-015","unit":6,"type":"definitie","front":"Cum este generată suprafața prismatică?","back":"De o dreaptă mobilă care se sprijină pe un poligon plan și rămâne tot timpul paralelă cu o dreaptă dată.","source":{"kind":"sarbu","page":46},"source_text":"Sârbu (2017), p. 46","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-016","unit":6,"type":"definitie","front":"Cum se obține prisma din suprafața prismatică?","back":"Intersectând suprafața prismatică cu două plane, astfel încât fiecare plan să intersecteze toate muchiile. Pentru prisma uzuală, cele două plane sunt paralele, iar bazele sunt congruente.","source":{"kind":"sarbu+curs_extins","page":46},"source_text":"Sârbu (2017), p. 46 + precizare din Cursul extins","tags":["U06","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U06-017","unit":6,"type":"explicativ","front":"Ce proprietate au muchiile laterale ale unei prisme?","back":"Au toate același vector director: sunt paralele și egale.","source":{"kind":"curs_extins","pdf_page":70},"source_text":"Curs universitar extins, p. PDF 70","tags":["U06","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U06-018","unit":6,"type":"definitie","front":"Ce este piramida?","back":"Poliedrul determinat de o bază poligonală plană și de un vârf exterior planului bazei, unit prin muchii cu vârfurile bazei.","source":{"kind":"curs_extins","pdf_page":68},"source_text":"Curs universitar extins, p. PDF 68","tags":["U06","tip::definitie","sursa::Curs_extins"]},{"id":"GD-U06-019","unit":6,"type":"definitie","front":"Piramida oblică SABCD din manual (Fig. 6.4.2): ce contur aparent are pe H și pe V?","back":"Pe H: poligonul convex absda.\nPe V: poligonul a′s′c′a′.","source":{"kind":"sarbu","page":47},"source_text":"Sârbu (2017), p. 47","tags":["U06","tip::definitie","sursa::Sarbu"]},{"id":"GD-U06-020","unit":6,"type":"formula","front":"Ce este relația lui Euler pentru poliedre convexe?","back":"V − E + F = 2 (vârfuri − muchii + fețe). Cub: 8 − 12 + 6 = 2; tetraedru: 4 − 6 + 4 = 2.","source":{"kind":"curs_extins","pdf_page":68},"source_text":"Curs universitar extins, p. PDF 68","tags":["U06","tip::formula","sursa::Curs_extins"]},{"id":"GD-U06-021","unit":6,"type":"capcana","front":"Conturul aparent al oricărui poliedru este convex?","back":"Nu. Doar pentru poliedre convexe. O prismă cu bază în formă de L are pe H un contur neconvex.","source":{"kind":"curs_extins","pdf_page":69},"source_text":"Curs universitar extins, p. PDF 69","tags":["U06","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U06-022","unit":6,"type":"capcana","front":"Muchia laterală a unei prisme oblice: lungimea reală e egală cu proiecția ei verticală?","back":"În general, proiecția pe V este mai scurtă, dar există egalitate pentru o muchie paralelă cu V. Pentru d=(dx;dy;dz): L=√(dx²+dy²+dz²), L_V=√(dx²+dz²)≤L; egalitate dacă dy=0. Înălțimea față de o bază orizontală este |dz|. Pentru d=(1;0,5;2) m: L=√5,25 m, L_V=√5 m, iar |dz|=2 m.","source":{"kind":"curs_extins","pdf_page":70},"source_text":"Curs universitar extins, p. PDF 70","tags":["U06","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U06-023","unit":6,"type":"procedeu","front":"Ce trebuie precizat ca să reprezinți corect un poliedru?","back":"Coordonatele vârfurilor, ce vârfuri sunt unite prin muchii, ce fețe delimitează muchiile și din ce sens se privește corpul.","source":{"kind":"curs_extins","pdf_page":69},"source_text":"Curs universitar extins, p. PDF 69","tags":["U06","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U06-024","unit":6,"type":"capcana","front":"Ce se întâmplă dacă vârful S al unei piramide este în planul bazei?","back":"Piramida degenerează: volumul este zero și nu mai este un corp tridimensional.","source":{"kind":"curs_extins","pdf_page":72},"source_text":"Curs universitar extins, p. PDF 72","tags":["U06","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U06-025","unit":6,"type":"lucrare","front":"Lucrarea de verificare nr. 6: ce cerințe are și cu ce punctaj?","back":"1. Ce sunt poliedrele? Clasificarea lor (3 p)\n2. Reprezentarea în epură a prismei (4 p)\n3. Reprezentarea în epură a piramidei (3 p)","source":{"kind":"sarbu","page":48},"source_text":"Sârbu (2017), p. 48","tags":["U06","tip::lucrare","sursa::Sarbu","lucrare::L06"]},{"id":"GD-U07-001","unit":7,"type":"definitie","front":"Ce este cilindrul (suprafața cilindrică)?","back":"Suprafața generată de o dreaptă care se deplasează paralel cu o direcție dată, sprijinindu-se pe o curbă directoare dată.","source":{"kind":"sarbu","page":49},"source_text":"Sârbu (2017), p. 49","tags":["U07","tip::definitie","sursa::Sarbu"]},{"id":"GD-U07-002","unit":7,"type":"definitie","front":"Ce este conul (suprafața conică)?","back":"Suprafața a cărei generatoare dreaptă trece printr-un punct fix (vârful) și se sprijină pe o curbă oarecare (directoarea).","source":{"kind":"sarbu","page":50},"source_text":"Sârbu (2017), p. 50","tags":["U07","tip::definitie","sursa::Sarbu"]},{"id":"GD-U07-003","unit":7,"type":"definitie","front":"Ce este sfera?","back":"Suprafața care ia naștere prin rotirea unui cerc în jurul unuia din diametrele sale.","source":{"kind":"sarbu","page":51},"source_text":"Sârbu (2017), p. 51","tags":["U07","tip::definitie","sursa::Sarbu"]},{"id":"GD-U07-004","unit":7,"type":"formula","front":"Ce este sfera ca loc geometric?","back":"Locul punctelor aflate la distanța constantă R de un centru G: (x−xG)² + (y−yG)² + (z−zG)² = R².","source":{"kind":"curs_extins","pdf_page":80},"source_text":"Curs universitar extins, p. PDF 80","tags":["U07","tip::formula","sursa::Curs_extins"]},{"id":"GD-U07-005","unit":7,"type":"definitie","front":"Ce este un cilindru drept circular?","back":"Cilindrul a cărui directoare este un cerc situat într-un plan perpendicular pe generatoare.","source":{"kind":"curs_extins","pdf_page":75},"source_text":"Curs universitar extins, p. PDF 75","tags":["U07","tip::definitie","sursa::Curs_extins"]},{"id":"GD-U07-006","unit":7,"type":"definitie","front":"Ce este un con drept circular?","back":"Conul cu baza un cerc și vârful pe perpendiculara dusă prin centrul bazei.","source":{"kind":"curs_extins","pdf_page":75},"source_text":"Curs universitar extins, p. PDF 75","tags":["U07","tip::definitie","sursa::Curs_extins"]},{"id":"GD-U07-007","unit":7,"type":"capcana","front":"Orice cilindru sau con este un corp de rotație?","back":"Nu. Doar cazurile drepte circulare au simetrie de rotație; un cilindru sau un con oblic nu este, în general, corp de rotație.","source":{"kind":"curs_extins","pdf_page":75},"source_text":"Curs universitar extins, p. PDF 75","tags":["U07","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U07-008","unit":7,"type":"explicativ","front":"Cum se proiectează un cilindru drept circular cu axa verticală?","back":"Pe H: un cerc. Pe V: un dreptunghi de lățime 2R și înălțime h.","source":{"kind":"curs_extins","pdf_page":80},"source_text":"Curs universitar extins, p. PDF 80","tags":["U07","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U07-009","unit":7,"type":"explicativ","front":"Cum se proiectează un con drept circular cu axa verticală?","back":"Pe H: cercul bazei (cu vârful în centru). Pe V: un triunghi (conturul aparent).","source":{"kind":"curs_extins","pdf_page":80},"source_text":"Curs universitar extins, p. PDF 80","tags":["U07","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U07-010","unit":7,"type":"explicativ","front":"Cum se proiectează sfera pe H și pe V?","back":"Ca două cercuri de rază R, cu centrele în proiecțiile centrului g și g′.","source":{"kind":"curs_extins","pdf_page":80},"source_text":"Curs universitar extins, p. PDF 80","tags":["U07","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U07-011","unit":7,"type":"formula","front":"Care este raza cercului de nivel z = z₀ al unei sfere de centru G și rază R?","back":"r = √(R² − (z₀ − zG)²), cu condiția |z₀ − zG| ≤ R.","source":{"kind":"curs_extins","pdf_page":75},"source_text":"Curs universitar extins, p. PDF 75","tags":["U07","tip::formula","sursa::Curs_extins"]},{"id":"GD-U07-012","unit":7,"type":"formula","front":"Când planul de nivel e tangent la sferă și când nu o taie?","back":"|z₀ − zG| = R: tangent, secțiunea e un punct.\n|z₀ − zG| > R: nu există intersecție reală.","source":{"kind":"curs_extins","pdf_page":75},"source_text":"Curs universitar extins, p. PDF 75","tags":["U07","tip::formula","sursa::Curs_extins"]},{"id":"GD-U07-013","unit":7,"type":"explicativ","front":"Cum apare cercul de nivel al sferei pe H și pe V?","back":"Pe H în adevărată mărime (cerc de rază r). Pe V ca un segment orizontal de lungime 2r.","source":{"kind":"curs_extins","pdf_page":79},"source_text":"Curs universitar extins, p. PDF 79","tags":["U07","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U07-014","unit":7,"type":"capcana","front":"Știi doar proiecția p a unui punct de pe sferă. Câte puncte corespund?","back":"De regulă două: z = zG ± √(R² − (x−xG)² − (y−yG)²). Pe conturul aparent, cele două coincid.","source":{"kind":"curs_extins","pdf_page":79},"source_text":"Curs universitar extins, p. PDF 79","tags":["U07","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U07-015","unit":7,"type":"recunoastere","front":"Dintre cele două puncte de pe sferă cu aceeași proiecție p, care e vizibil pe H?","back":"Cel de sus (emisfera superioară), privind dinspre +Z.","source":{"kind":"curs_extins","pdf_page":76},"source_text":"Curs universitar extins, p. PDF 76","tags":["U07","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U07-016","unit":7,"type":"capcana","front":"Poți afla cota unui punct de pe un cilindru vertical doar din proiecția lui pe H?","back":"Nu. Generatoarea prin acel punct e verticală, deci orice cotă între baze e posibilă; ai nevoie de date suplimentare.","source":{"kind":"curs_extins","pdf_page":77},"source_text":"Curs universitar extins, p. PDF 77","tags":["U07","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U07-017","unit":7,"type":"formula","front":"Cum variază raza secțiunilor orizontale ale unui con drept circular?","back":"Secțiunile la cote fixe sunt cercuri; raza descrește liniar de la R (la bază) la 0 (la vârf): r = R(1 − z/h).","source":{"kind":"curs_extins","pdf_page":77},"source_text":"Curs universitar extins, p. PDF 77","tags":["U07","tip::formula","sursa::Curs_extins"]},{"id":"GD-U07-018","unit":7,"type":"procedeu","front":"Cum construiești proiecția verticală a unui punct de pe con cunoscând proiecția orizontală?","back":"Duci generatoarea prin acel punct (de la vârf la bază), îi construiești proiecția pe V și cobori linia de ordine pe ea. Sau folosești cercul de nivel al punctului.","source":{"kind":"curs_extins","pdf_page":76},"source_text":"Curs universitar extins, p. PDF 76","tags":["U07","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U07-019","unit":7,"type":"capcana","front":"La un con oblic, o proiectantă verticală poate întâlni suprafața în mai multe puncte?","back":"Da: în două puncte, într-un punct tangent sau în niciunul, după poziție. Trebuie verificate generatoarele și vizibilitatea.","source":{"kind":"curs_extins","pdf_page":76},"source_text":"Curs universitar extins, p. PDF 76","tags":["U07","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U07-020","unit":7,"type":"explicativ","front":"Care suprafețe din curs se pot desfășura pe plan și care nu?","back":"Cilindrul și conul se pot desfășura (curbură Gauss zero în punctele regulate). Sfera nu se poate desfășura fără deformare.","source":{"kind":"curs_extins","pdf_page":77},"source_text":"Curs universitar extins, p. PDF 77","tags":["U07","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U07-021","unit":7,"type":"lucrare","front":"Lucrarea de verificare nr. 7: ce cerințe are și cu ce punctaj?","back":"1. Definiția și reprezentarea cilindrului (3 p)\n2. Definiția și reprezentarea conului (4 p)\n3. Definiția și reprezentarea sferei (3 p)","source":{"kind":"sarbu","page":52},"source_text":"Sârbu (2017), p. 52","tags":["U07","tip::lucrare","sursa::Sarbu","lucrare::L07"]},{"id":"GD-U08-001","unit":8,"type":"definitie","front":"Cum se determină secțiunea plană a unei suprafețe cilindrico-conice (procedeul din manual)?","back":"Ca la poliedre: suprafața e privită ca un poliedru cu foarte multe muchii, care devin generatoare. Punctele curbei de secțiune sunt punctele în care generatoarele intersectează planul secant.","source":{"kind":"sarbu","page":53},"source_text":"Sârbu (2017), p. 53","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-002","unit":8,"type":"definitie","front":"Ce exemplu de secțiune cu plan proiectant dă manualul pentru cilindru?","back":"Secțiunea cu un plan de capăt a unui cilindru oarecare (Fig. 8.2.1).","source":{"kind":"sarbu","page":53},"source_text":"Sârbu (2017), p. 53","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-003","unit":8,"type":"recunoastere","front":"Plan secant de capăt: unde se află proiecția verticală a secțiunii?","back":"Pe urma Pv, doar porțiunea limitată de suprafață (nu întreaga dreaptă Pv).","source":{"kind":"curs_extins","pdf_page":82},"source_text":"Curs universitar extins, p. PDF 82","tags":["U08","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U08-004","unit":8,"type":"procedeu","front":"Care sunt pașii secționării unei suprafețe cu un plan de capăt?","back":"1. Proiectezi generatoarele și urma Pv.\n2. Găsești intersecțiile generatoarelor cu Pv.\n3. Prin linii de ordine obții proiecțiile pe H.\n4. Ordonezi punctele și stabilești vizibilitatea.\n5. Adevărata mărime: prin rabatere.","source":{"kind":"curs_extins","pdf_page":81},"source_text":"Curs universitar extins, p. PDF 81","tags":["U08","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U08-005","unit":8,"type":"capcana","front":"Cilindru drept vertical secționat de un plan înclinat: ce vezi pe H?","back":"Cercul bazei, dacă planul taie complet mantaua cilindrului vertical și secțiunea nu este limitată de baze. Cercul este proiecția secțiunii, nu adevărata ei mărime, obținută prin rabatere. Pentru un cilindru finit traversat numai parțial, proiecția porțiunii de pe manta poate fi doar un arc de cerc.","source":{"kind":"curs_extins","pdf_page":85},"source_text":"Curs universitar extins, p. PDF 85","tags":["U08","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U08-006","unit":8,"type":"capcana","front":"Poți lua 2πR ca lungime a secțiunii oblice a unui cilindru?","back":"Nu. 2πR este lungimea cercului proiectat; curba reală (o elipsă) e mai lungă când planul e înclinat.","source":{"kind":"curs_extins","pdf_page":85},"source_text":"Curs universitar extins, p. PDF 85","tags":["U08","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U08-007","unit":8,"type":"recunoastere","front":"Secțiuni în con dublu drept circular: planul e perpendicular pe axă (α = 90°).","back":"Cerc.","source":{"kind":"curs_extins","pdf_page":81},"source_text":"Curs universitar extins, p. PDF 81","tags":["U08","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U08-008","unit":8,"type":"recunoastere","front":"Secțiuni în con: unghiul α dintre plan și axă e între θ (semiunghiul conului) și 90°.","back":"Elipsă.","source":{"kind":"curs_extins","pdf_page":81},"source_text":"Curs universitar extins, p. PDF 81","tags":["U08","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U08-009","unit":8,"type":"recunoastere","front":"Secțiuni în con: planul face cu axa unghiul α = θ (paralel cu o generatoare).","back":"Parabolă.","source":{"kind":"curs_extins","pdf_page":81},"source_text":"Curs universitar extins, p. PDF 81","tags":["U08","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U08-010","unit":8,"type":"recunoastere","front":"Secțiuni în con: planul face cu axa un unghi α < θ (taie ambele pânze).","back":"Hiperbolă.","source":{"kind":"curs_extins","pdf_page":81},"source_text":"Curs universitar extins, p. PDF 81","tags":["U08","tip::recunoastere","sursa::Curs_extins"]},{"id":"GD-U08-011","unit":8,"type":"capcana","front":"În ce condiții e valabilă clasificarea cerc / elipsă / parabolă / hiperbolă după α și θ?","back":"Pentru un con dublu drept circular și un plan secant care nu trece prin vârf.","source":{"kind":"curs_extins","pdf_page":81},"source_text":"Curs universitar extins, p. PDF 81","tags":["U08","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U08-012","unit":8,"type":"definitie","front":"Ce tipuri de intersecții ale suprafețelor prezintă manualul?","back":"Prin pătrunderi și prin smulgeri.","source":{"kind":"sarbu","page":54},"source_text":"Sârbu (2017), p. 54","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-013","unit":8,"type":"definitie","front":"Ce este pătrunderea?","back":"Intersecția în care una dintre suprafețe pătrunde complet în cealaltă: toate generatoarele primei suprafețe o intersectează pe a doua.","source":{"kind":"sarbu","page":54},"source_text":"Sârbu (2017), p. 54","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-014","unit":8,"type":"definitie","front":"Ce formă are curba de intersecție la pătrundere?","back":"Două ramuri: una de intrare și una de ieșire.","source":{"kind":"sarbu","page":54},"source_text":"Sârbu (2017), p. 54","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-015","unit":8,"type":"definitie","front":"Ce este smulgerea (ruperea)?","back":"Intersecția în care o suprafață pătrunde parțial în cealaltă: fiecare suprafață rămâne cu generatoare care nu o intersectează pe cealaltă.","source":{"kind":"sarbu","page":55},"source_text":"Sârbu (2017), p. 55","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-016","unit":8,"type":"definitie","front":"Ce formă are curba de intersecție la smulgere?","back":"O curbă cu o singură ramură.","source":{"kind":"sarbu","page":55},"source_text":"Sârbu (2017), p. 55","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-017","unit":8,"type":"definitie","front":"Ce este cazul intermediar între pătrundere și smulgere?","back":"Curba de intrare și cea de ieșire au un punct comun prin care se poate duce un plan tangent în același timp la ambele suprafețe.","source":{"kind":"sarbu","page":55},"source_text":"Sârbu (2017), p. 55","tags":["U08","tip::definitie","sursa::Sarbu"]},{"id":"GD-U08-018","unit":8,"type":"recunoastere","front":"Toate generatoarele primei suprafețe o intersectează pe a doua. Ce tip de intersecție este?","back":"Pătrundere (curbă cu două ramuri).","source":{"kind":"sarbu","page":54},"source_text":"Sârbu (2017), p. 54","tags":["U08","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U08-019","unit":8,"type":"recunoastere","front":"Fiecare suprafață păstrează generatoare care nu o ating pe cealaltă. Ce tip de intersecție este?","back":"Smulgere sau rupere (curbă cu o singură ramură).","source":{"kind":"sarbu","page":55},"source_text":"Sârbu (2017), p. 55","tags":["U08","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U08-020","unit":8,"type":"capcana","front":"În cazul intermediar, se ating ramurile curbei cu aceeași tangentă?","back":"Nu neapărat. În configurațiile din curs, ramurile se întâlnesc în acel punct; tangentele lor pot fi diferite. Existența unui plan tangent comun celor două suprafețe nu implică automat un nod al curbei (suport extins V2.1, Anexa A, A27).","source":{"kind":"curs_extins","pdf_page":82},"source_text":"Curs universitar extins, p. PDF 82","tags":["U08","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U08-021","unit":8,"type":"procedeu","front":"Cum găsești puncte ale curbei de intersecție a două suprafețe (metoda planelor auxiliare)?","back":"Tai ambele suprafețe cu un plan auxiliar ales astfel încât secțiunile să fie simple (drepte sau cercuri). Punctele comune ale celor două secțiuni aparțin curbei. Repeți cu mai multe plane.","source":{"kind":"curs_extins","pdf_page":82},"source_text":"Curs universitar extins, p. PDF 82","tags":["U08","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U08-022","unit":8,"type":"capcana","front":"Numărul de ramuri (două / una) este o teoremă valabilă pentru orice intersecție de suprafețe?","back":"Nu. Pătrunderea și smulgerea sunt clasificări grafice ale cazurilor ilustrate, nu teoreme generale.","source":{"kind":"curs_extins","pdf_page":82},"source_text":"Curs universitar extins, p. PDF 82","tags":["U08","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U08-023","unit":8,"type":"lucrare","front":"Lucrarea de verificare nr. 8: ce cerințe are și cu ce punctaj?","back":"1. Procedeul de secționare cu un plan proiectant (3 p)\n2. Un exemplu de secțiune în suprafețe cilindrico-conice (4 p)\n3. Tipurile de intersecții ale suprafețelor (3 p)","source":{"kind":"sarbu","page":56},"source_text":"Sârbu (2017), p. 56","tags":["U08","tip::lucrare","sursa::Sarbu","lucrare::L08"]},{"id":"GD-U09-001","unit":9,"type":"definitie","front":"Ce se înțelege prin desfășurarea unui poliedru?","back":"Aducerea tuturor fețelor lui în același plan.","source":{"kind":"sarbu","page":57},"source_text":"Sârbu (2017), p. 57","tags":["U09","tip::definitie","sursa::Sarbu"]},{"id":"GD-U09-002","unit":9,"type":"definitie","front":"Ce sunt „transformatele prin desfășurare”?","back":"Punctele și liniile din figura desfășurată care corespund punctelor și liniilor trase pe suprafața poliedrului.","source":{"kind":"sarbu","page":57},"source_text":"Sârbu (2017), p. 57","tags":["U09","tip::definitie","sursa::Sarbu"]},{"id":"GD-U09-003","unit":9,"type":"definitie","front":"Ce desfășurări ilustrează manualul în Unitatea 9?","back":"Prismă oblică și piramidă oblică (Fig. 9.2.1, 9.2.2); cilindru și con (Fig. 9.3.1, 9.3.2).","source":{"kind":"sarbu","page":58},"source_text":"Sârbu (2017), p. 58","tags":["U09","tip::definitie","sursa::Sarbu"]},{"id":"GD-U09-004","unit":9,"type":"explicativ","front":"Ce păstrează o desfășurare corectă?","back":"Lungimile măsurate pe suprafață și unghiurile din fiecare față. La poliedre, fiecare față se rotește rigid în plan; unghiurile diedre dintre fețe nu se păstrează.","source":{"kind":"curs_extins","pdf_page":89},"source_text":"Curs universitar extins, p. PDF 89","tags":["U09","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U09-005","unit":9,"type":"explicativ","front":"Se poate desfășura o suprafață închisă fără tăieturi?","back":"Nu. O deschizi pe o muchie sau pe o generatoare (de ex. tai prisma pe o muchie laterală).","source":{"kind":"curs_extins","pdf_page":89},"source_text":"Curs universitar extins, p. PDF 89","tags":["U09","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U09-006","unit":9,"type":"procedeu","front":"Ce metodă se folosește pentru desfășurarea unei prisme oblice?","back":"Secțiunea dreaptă: un plan perpendicular pe muchiile laterale. Laturile secțiunii (în adevărată mărime) se pun în linie, iar pe perpendiculare se reportează lungimile reale ale muchiilor până la baze.","source":{"kind":"curs_extins","pdf_page":89},"source_text":"Curs universitar extins, p. PDF 89","tags":["U09","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U09-007","unit":9,"type":"procedeu","front":"Ce verifici la desfășurarea unei prisme?","back":"Suma laturilor = perimetrul secțiunii drepte; muchiile paralele în spațiu rămân paralele; marginile se închid fără salturi; toate valorile sunt lungimi reale.","source":{"kind":"curs_extins","pdf_page":89},"source_text":"Curs universitar extins, p. PDF 89","tags":["U09","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U09-008","unit":9,"type":"procedeu","front":"Cum desfășori o piramidă oblică?","back":"Prin triunghiuri: pentru fiecare față SAᵢAᵢ₊₁ calculezi lungimile reale ale celor trei laturi și construiești triunghiul cu compasul; alipești fețele pe muchiile comune.","source":{"kind":"curs_extins","pdf_page":89},"source_text":"Curs universitar extins, p. PDF 89","tags":["U09","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U09-009","unit":9,"type":"capcana","front":"La desfășurare poți folosi lungimile proiecțiilor muchiilor?","back":"Folosești numai lungimi reale. O proiecție poate fi folosită direct dacă muchia este paralelă cu planul de proiecție, astfel încât apare în adevărată mărime. Dacă proiecția este prescurtată, determini mai întâi lungimea reală printr-o metodă din Unitatea 5.","source":{"kind":"curs_extins","pdf_page":94},"source_text":"Curs universitar extins, p. PDF 94","tags":["U09","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U09-010","unit":9,"type":"explicativ","front":"La închiderea desfășurării unei piramide, ce se repetă?","back":"Muchia pe care ai tăiat (de ex. SA) apare la ambele capete, iar vârful A apare de două ori (A și copia A*).","source":{"kind":"curs_extins","pdf_page":90},"source_text":"Curs universitar extins, p. PDF 90","tags":["U09","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U09-011","unit":9,"type":"formula","front":"În ce se desfășoară mantaua unui cilindru drept circular (R, înălțime H)?","back":"Într-un dreptunghi de lungime 2πR și înălțime H.","source":{"kind":"curs_extins","pdf_page":90},"source_text":"Curs universitar extins, p. PDF 90","tags":["U09","tip::formula","sursa::Curs_extins"]},{"id":"GD-U09-012","unit":9,"type":"formula","front":"Cilindru drept tăiat de un plan înclinat: cum arată marginea în desfășurare?","back":"O curbă cosinusoidală: z(s) = h₀ + kR·cos(s/R). Cilindrul are axa OZ, x = R cos θ; planul secant este z = h₀ + kx; s = Rθ se măsoară de la generatoarea cu x = R. h₀ este cota planului pe axa cilindrului, k panta, R raza, iar θ unghiul în radiani.","source":{"kind":"curs_extins","pdf_page":90},"source_text":"Curs universitar extins, p. PDF 90","tags":["U09","tip::formula","sursa::Curs_extins"]},{"id":"GD-U09-013","unit":9,"type":"procedeu","front":"Ce control de închidere faci la desfășurarea cilindrului secționat?","back":"Înălțimea la s = 0 și la s = 2πR trebuie să fie aceeași.","source":{"kind":"curs_extins","pdf_page":96},"source_text":"Curs universitar extins, p. PDF 95–96","tags":["U09","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U09-014","unit":9,"type":"explicativ","front":"De ce lungimea desfășurată a arcului de cilindru este Rθ (și nu 2Rθ)?","back":"Extensie (suport extins), justificare metrică: Pe manta, dl² = R²dθ² + dz²; cu s = Rθ devine dl² = ds² + dz², deci lungimile se păstrează.","source":{"kind":"curs_extins","pdf_page":96},"source_text":"Curs universitar extins, p. PDF 96","tags":["U09","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U09-015","unit":9,"type":"formula","front":"Cum calculezi generatoarea G a unui con drept circular?","back":"G = √(R² + h²).","source":{"kind":"curs_extins","pdf_page":91},"source_text":"Curs universitar extins, p. PDF 91","tags":["U09","tip::formula","sursa::Curs_extins"]},{"id":"GD-U09-016","unit":9,"type":"formula","front":"În ce se desfășoară mantaua unui con drept circular?","back":"Într-un sector de cerc cu raza G și unghiul la centru φ = 360°·R/G (= 2πR/G radiani).","source":{"kind":"curs_extins","pdf_page":91},"source_text":"Curs universitar extins, p. PDF 91","tags":["U09","tip::formula","sursa::Curs_extins"]},{"id":"GD-U09-017","unit":9,"type":"procedeu","front":"Cum verifici sectorul conului desfășurat?","back":"Arcul sectorului trebuie să fie egal cu circumferința bazei: G·φ=2πR, cu φ în radiani. Dacă unghiul este exprimat în grade, verifici G·φ·π/180=2πR. De exemplu, R=1 m și G=3 m dau φ=120°=2π/3 rad.","source":{"kind":"curs_extins","pdf_page":96},"source_text":"Curs universitar extins, p. PDF 96","tags":["U09","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U09-018","unit":9,"type":"capcana","front":"Formula sectorului φ = 360°·R/G e valabilă pentru orice con?","back":"Nu, doar pentru conul drept circular. La un con oblic generatoarele nu au aceeași lungime.","source":{"kind":"curs_extins","pdf_page":97},"source_text":"Curs universitar extins, p. PDF 97","tags":["U09","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U09-019","unit":9,"type":"procedeu","front":"Cum transpui pe desfășurarea conului un punct de secțiune?","back":"Pe generatoarea care face unghiul θ pe bază pui unghiul ψ = (R/G)·θ în sector, iar pe ea reportezi lungimea reală de la vârf la punct.","source":{"kind":"curs_extins","pdf_page":92},"source_text":"Curs universitar extins, p. PDF 92","tags":["U09","tip::procedeu","sursa::Curs_extins"]},{"id":"GD-U09-020","unit":9,"type":"capcana","front":"Poți folosi proiecția verticală a unei generatoare oblice drept lungime reală?","back":"Da, numai dacă generatoarea este paralelă cu V și proiecția ei apare în adevărată mărime. Oblicitatea față de axa conului nu exclude acest caz frontal. Dacă generatoarea este oblică față de V, proiecția este prescurtată: afli lungimea reală printr-o metodă din Unitatea 5, apoi o reporți pe desfășurare.","source":{"kind":"curs_extins","pdf_page":97},"source_text":"Curs universitar extins, p. PDF 97","tags":["U09","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U09-021","unit":9,"type":"capcana","front":"La p. 60, manualul trimite pentru desfășurarea cilindrului și a conului la Fig. 9.2.1 și 9.2.2. Care sunt figurile corecte?","back":"Fig. 9.3.1 (cilindru) și Fig. 9.3.2 (con). 9.2.1 și 9.2.2 sunt prisma și piramida.","source":{"kind":"curs_extins","pdf_page":92},"source_text":"Curs universitar extins, p. PDF 92","tags":["U09","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U09-022","unit":9,"type":"lucrare","front":"Lucrarea de verificare nr. 9: ce cerințe are și cu ce punctaj?","back":"1. Desfășurarea unei prisme oblice sau a unei piramide oblice (5 p)\n2. Desfășurarea unui cilindru sau a unui con (5 p)","source":{"kind":"sarbu","page":60},"source_text":"Sârbu (2017), p. 60","tags":["U09","tip::lucrare","sursa::Sarbu","lucrare::L09"]},{"id":"GD-U10-001","unit":10,"type":"definitie","front":"Ce este desenul tehnic, după manual?","back":"Reprezentarea grafică plană a unor obiecte, piese, construcții, instalații etc., la care se folosesc metodele geometriei descriptive și o serie de reguli și convenții (standarde).","source":{"kind":"sarbu","page":61},"source_text":"Sârbu (2017), p. 61","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-002","unit":10,"type":"definitie","front":"Ce sunt formatele și prin ce standard sunt stabilite în manual?","back":"Spații dreptunghiulare pe care se prezintă desenele, cu dimensiuni stabilite prin STAS 1-84.","source":{"kind":"sarbu","page":61},"source_text":"Sârbu (2017), p. 61","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-003","unit":10,"type":"definitie","front":"Ce raport au laturile formatelor?","back":"1 : √2 (raport constant între lungime și lățime).","source":{"kind":"sarbu","page":61},"source_text":"Sârbu (2017), p. 61","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-004","unit":10,"type":"explicativ","front":"De ce raportul 1 : √2?","back":"Un dreptunghi cu acest raport, tăiat în două paralel cu latura scurtă, dă două dreptunghiuri cu același raport (de ex. A3 → două A4).","source":{"kind":"curs_extins","pdf_page":99},"source_text":"Curs universitar extins, p. PDF 99","tags":["U10","tip::explicativ","sursa::Curs_extins"]},{"id":"GD-U10-005","unit":10,"type":"definitie","front":"Ce suprafață are formatul A0?","back":"1 m².","source":{"kind":"sarbu","page":61},"source_text":"Sârbu (2017), p. 61","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-006","unit":10,"type":"definitie","front":"Cum se notează formatele?","back":"Cu litera A urmată de o cifră care indică tipul formatului și dimensiunile.","source":{"kind":"sarbu","page":61},"source_text":"Sârbu (2017), p. 61","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-007","unit":10,"type":"definitie","front":"În ce categorii se împart formatele după dimensiuni?","back":"a) formate preferențiale (de bază)\nb) formate alungite speciale\nc) formate alungite excepționale","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-008","unit":10,"type":"definitie","front":"Dimensiunile formatului A0?","back":"841 × 1189 mm.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-009","unit":10,"type":"definitie","front":"Dimensiunile formatului A1?","back":"594 × 841 mm.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-010","unit":10,"type":"definitie","front":"Dimensiunile formatului A2?","back":"420 × 594 mm.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-011","unit":10,"type":"definitie","front":"Dimensiunile formatului A3?","back":"297 × 420 mm.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-012","unit":10,"type":"definitie","front":"Dimensiunile formatului A4?","back":"210 × 297 mm.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-013","unit":10,"type":"definitie","front":"Cum se obțin formatele alungite speciale?","back":"Prin alungirea dimensiunii a a formatului de bază, astfel încât lungimea b să fie un multiplu întreg al lui a. Multiplul apare în simbol (de ex. A3 × 3).","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-014","unit":10,"type":"definitie","front":"Care sunt formatele alungite speciale și dimensiunile lor?","back":"A3×3: 420 × 891\nA3×4: 420 × 1189\nA4×3: 297 × 630\nA4×4: 297 × 841\nA4×5: 297 × 1051 (mm)","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-015","unit":10,"type":"definitie","front":"Ce formate alungite excepționale enumeră manualul?","back":"A0×2, A0×3; A1×3, A1×4; A2×3, A2×4, A2×5; A3×5, A3×6, A3×7; A4×6, A4×7, A4×8, A4×9.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-016","unit":10,"type":"definitie","front":"Pe ce format se recomandă executarea desenului?","back":"Pe cel mai mic format care permite reprezentarea clară. Formatele alungite (speciale, excepționale) se folosesc numai dacă obiectul nu încape pe un format de bază.","source":{"kind":"sarbu","page":62},"source_text":"Sârbu (2017), p. 62","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-017","unit":10,"type":"definitie","front":"Ce este zona neutră și ce lățime are?","back":"Zona dintre conturul pentru decuparea copiei și chenar. Lățime: 10 mm pentru A0, A1, A2, A3 și alungitele lor; 5 mm pentru A4.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-018","unit":10,"type":"definitie","front":"Ce este chenarul și cum se execută?","back":"Linia care delimitează câmpul desenului; se execută cu linie continuă de 0,5 mm grosime.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-019","unit":10,"type":"definitie","front":"Ce este fâșia de îndosariere și ce dimensiuni are?","back":"Spațiul pentru perforarea copiei, pe latura din stânga indicatorului, la toate formatele: 20 × 297 mm, cu linie continuă subțire.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-020","unit":10,"type":"definitie","front":"Unde se plasează indicatorul?","back":"În colțul din dreapta jos; poate fi așezat atât pe latura lungă (b), cât și pe cea scurtă (a) a formatului.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-021","unit":10,"type":"definitie","front":"Cum se amplasează indicatorul desenului de construcții?","back":"În colțul din dreapta jos al planșei, alipit de chenar, cu latura lungă paralelă cu baza formatului.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-022","unit":10,"type":"definitie","front":"Ce mărimi de indicator există în desenul de construcții și când se folosesc?","back":"Mare: formate mai mari decât A3.\nMic: formate egale sau mai mici decât A3.\nÎngust: proiecte și detalii tip, multiplicate și prin tipar.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-023","unit":10,"type":"definitie","front":"Ce dimensiuni au indicatoarele?","back":"Mare: 185 × 50 mm\nMic: 120 × 40 mm\nÎngust: 185 × 25 mm","source":{"kind":"sarbu","page":70},"source_text":"Sârbu (2017), p. 70","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-024","unit":10,"type":"recunoastere","front":"Desenezi pe un format A2. Ce indicator folosești?","back":"Indicatorul mare (185 × 50 mm), deoarece A2 este mai mare decât A3.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-025","unit":10,"type":"recunoastere","front":"Desenezi pe un format A4. Ce indicator folosești?","back":"Indicatorul mic (120 × 40 mm), deoarece A4 este mai mic decât A3.","source":{"kind":"sarbu","page":63},"source_text":"Sârbu (2017), p. 63","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-026","unit":10,"type":"definitie","front":"Cu ce linii se trasează indicatorul?","back":"Cu linii continue groase (C1), cu excepția împărțirii căsuței 4, unde se folosește linia continuă subțire (C3).","source":{"kind":"sarbu","page":64},"source_text":"Sârbu (2017), p. 64","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-027","unit":10,"type":"definitie","front":"Ce se scrie în căsuțele 1, 2 și 3 ale indicatorului?","back":"1: instituția proiectantă (eventual subunitatea)\n2: denumirea proiectului, locul construcției, beneficiarul (la indicatorul îngust: denumirea proiectului tip)\n3: indicativul (numărul) proiectului","source":{"kind":"sarbu","page":64},"source_text":"Sârbu (2017), p. 64","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-028","unit":10,"type":"definitie","front":"Ce se scrie în căsuța 4 a indicatorului?","back":"Pe trei coloane: calitatea (proiectat, desenat, verificat, controlat STAS, aprobat), numele în clar și semnătura.","source":{"kind":"sarbu","page":64},"source_text":"Sârbu (2017), p. 64","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-029","unit":10,"type":"definitie","front":"Ce se scrie în căsuța 5 a indicatorului?","back":"Scara desenului și, dedesubt, data întocmirii sau a predării proiectului. Scările grafice, când există, se figurează deasupra indicatorului.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-030","unit":10,"type":"definitie","front":"Ce se scrie în căsuțele 6, 7 și 8 ale indicatorului?","back":"6: denumirea obiectului și titlul planșei\n7: faza de proiect\n8: indicativul (numărul de ordine) al planșei","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-031","unit":10,"type":"definitie","front":"Ce tipuri de linii se folosesc în desenul de construcții?","back":"Linia continuă (indicativ C), linia întreruptă (I) și linia-punct (P).","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-032","unit":10,"type":"definitie","front":"Între ce valori se alege grosimea de bază b a liniilor?","back":"Între 0,2 mm și 2 mm, după mărimea și natura desenului.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-033","unit":10,"type":"definitie","front":"Care sunt clasele de grosime a liniilor?","back":"1 = groasă (b)\n2 = mijlocie (≈ b/2)\n3 = subțire (≈ b/4)","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-034","unit":10,"type":"definitie","front":"La ce se folosește linia C1?","back":"Contururi de secțiune, tabele, chenare pentru desene și indicator.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-035","unit":10,"type":"definitie","front":"La ce se folosește linia C2?","back":"Contururi și muchii văzute în vederi; curbe de nivel principale; construcții geometrice.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-036","unit":10,"type":"definitie","front":"La ce se folosește linia C3?","back":"Linii de cotă, linii ajutătoare de cotă, hașuri, axe de goluri de uși și ferestre etc.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-037","unit":10,"type":"definitie","front":"Cu ce linie se trasează linia de ruptură?","back":"Cu linie subțire C3, cu zig-zag sau ondulată.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-038","unit":10,"type":"definitie","front":"La ce se folosește linia întreruptă mijlocie I2?","back":"Contururi și muchii acoperite de alte elemente.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-039","unit":10,"type":"definitie","front":"La ce se folosește linia întreruptă subțire I3?","back":"Părți situate în fața planului de secționare.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-040","unit":10,"type":"definitie","front":"La ce se folosește linia-punct mijlocie P2?","back":"Orice fel de axe, cu excepția celor trasate cu C3 și P3.","source":{"kind":"sarbu","page":66},"source_text":"Sârbu (2017), p. 66","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-041","unit":10,"type":"definitie","front":"La ce se folosește linia-punct subțire P3?","back":"Axele geometrice ale pieselor componente, traseele de secționare, liniile de întrerupere.","source":{"kind":"sarbu","page":66},"source_text":"Sârbu (2017), p. 66","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-042","unit":10,"type":"recunoastere","front":"Muchie ascunsă într-o vedere: ce linie (după manual)?","back":"I2: linie întreruptă mijlocie.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-043","unit":10,"type":"recunoastere","front":"Axa unui gol de ușă: ce linie (după manual)?","back":"C3: linie continuă subțire.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-044","unit":10,"type":"recunoastere","front":"Chenarul planșei: ce linie?","back":"C1: linie continuă groasă.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-045","unit":10,"type":"recunoastere","front":"Hașura unei secțiuni: ce linie?","back":"C3: linie continuă subțire.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-046","unit":10,"type":"recunoastere","front":"Conturul unei secțiuni: ce linie?","back":"C1: linie continuă groasă.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-047","unit":10,"type":"recunoastere","front":"Muchie vizibilă într-o vedere: ce linie (după manual)?","back":"C2: linie continuă mijlocie.","source":{"kind":"sarbu","page":65},"source_text":"Sârbu (2017), p. 65","tags":["U10","tip::recunoastere","sursa::Sarbu"]},{"id":"GD-U10-048","unit":10,"type":"definitie","front":"Ce moduri de scriere se folosesc în desenul tehnic?","back":"Scrierea dreaptă (caractere perpendiculare pe linia de bază) sau înclinată spre dreapta față de linia de bază; nu se folosesc ambele pe același desen.\nAtenție: manualul tipărește „75 %”; figura arată 75°.","source":{"kind":"sarbu+curs_extins","page":66},"source_text":"Sârbu (2017), p. 66 + precizare din Cursul extins","tags":["U10","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U10-049","unit":10,"type":"definitie","front":"Ce înălțimi nominale h ale literelor mari prevede manualul?","back":"2,5 – 3,5 – 5 – 7 – 10 – 14 – 20 mm, plus valorile obținute prin înmulțire cu 10.","source":{"kind":"sarbu","page":66},"source_text":"Sârbu (2017), p. 66","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-050","unit":10,"type":"definitie","front":"Care sunt tipurile de scriere A și B (grosimea liniei literelor)?","back":"Tipul A: ≈ h/14 („scriere normală”).\nTipul B: ≈ h/10 („scriere îngustată”).\nAșa le numește manualul.","source":{"kind":"sarbu","page":66},"source_text":"Sârbu (2017), p. 66","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-051","unit":10,"type":"definitie","front":"Cum se definește scara în desenul tehnic?","back":"Raportul dintre dimensiunea liniară a reprezentării unui segment pe desenul original și dimensiunea liniară reală a segmentului corespunzător.","source":{"kind":"sarbu","page":67},"source_text":"Sârbu (2017), p. 67","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-052","unit":10,"type":"definitie","front":"În ce trei forme se exprimă scara?","back":"1 : 1 (mărime naturală)\nX : 1 (scări de mărire)\n1 : X (scări de micșorare)","source":{"kind":"sarbu","page":67},"source_text":"Sârbu (2017), p. 67","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-053","unit":10,"type":"definitie","front":"Ce scări se folosesc în mod curent în desenul de construcții?","back":"Scări de micșorare, pentru că reprezentarea e mai mică decât elementul real.","source":{"kind":"sarbu","page":67},"source_text":"Sârbu (2017), p. 67","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-054","unit":10,"type":"definitie","front":"Care sunt scările de micșorare recomandate?","back":"1:2, 1:5, 1:10\n1:20, 1:50, 1:100\n1:200, 1:500, 1:1000\n1:2000, 1:5000, 1:10000","source":{"kind":"sarbu","page":67},"source_text":"Sârbu (2017), p. 67","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-055","unit":10,"type":"definitie","front":"Ce scări se admit doar în cazuri particulare?","back":"• scări obținute din cele recomandate prin multiplicare cu 10ⁿ\n• 1 : 2,5 × 10ⁿ (pentru folosirea câmpului desenului)\n• 1 : 15 (construcții metalice)\nAtenție: manualul spune că se înmulțește „numărătorul”; pentru micșorări mai mari (1:20 → 1:200) se înmulțește de fapt numitorul.","source":{"kind":"sarbu+curs_extins","page":67},"source_text":"Sârbu (2017), p. 67 + precizare din Cursul extins","tags":["U10","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U10-056","unit":10,"type":"formula","front":"Care e relația pentru scările de micșorare?","back":"d/R = 1/x, deci d = R/x\nd = dimensiunea pe desen, R = dimensiunea reală, x = numitorul scării.","source":{"kind":"sarbu","page":67},"source_text":"Sârbu (2017), p. 67","tags":["U10","tip::formula","sursa::Sarbu"]},{"id":"GD-U10-057","unit":10,"type":"formula","front":"La scara 1:20, cât reprezintă 1 m pe desen?","back":"5 cm (1 m / 20 = 0,05 m).","source":{"kind":"sarbu","page":67},"source_text":"Sârbu (2017), p. 67","tags":["U10","tip::formula","sursa::Sarbu"]},{"id":"GD-U10-058","unit":10,"type":"formula","front":"Ce lungime are pe desen un element de 3,60 m la scara 1:50?","back":"72 mm (3600 mm / 50).","source":{"kind":"curs_extins","pdf_page":101},"source_text":"Curs universitar extins, p. PDF 101","tags":["U10","tip::formula","sursa::Curs_extins"]},{"id":"GD-U10-059","unit":10,"type":"capcana","front":"Pe un desen la 1:50, un perete măsoară 72 mm. Ce cotă scrii?","back":"Valoarea reală: 3,60 (m). Cota este dimensiunea reală, nu lungimea desenată.","source":{"kind":"curs_extins","pdf_page":103},"source_text":"Curs universitar extins, p. PDF 103","tags":["U10","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U10-060","unit":10,"type":"definitie","front":"Ce este cotarea unui desen?","back":"Înscrierea în desen a dimensiunilor parțiale și totale necesare pentru determinarea precisă și clară a tuturor elementelor reprezentate.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-061","unit":10,"type":"definitie","front":"Care sunt elementele cotării?","back":"Cota, linia de cotă, liniile ajutătoare și liniile de indicație (de referință).","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-062","unit":10,"type":"definitie","front":"Ce este cota și unde se scrie?","back":"Valoarea numerică reală a dimensiunii. Se scrie imediat deasupra liniei de cotă (≈ 1 mm) și, pe cât posibil, la mijlocul intervalului.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-063","unit":10,"type":"definitie","front":"În ce unități se scriu cotele în desenul de construcții (după manual)?","back":"≥ 1,00 m: în metri, cu două zecimale (chiar dacă sunt zero).\n< 1,00 m: în centimetri.\nMilimetrii: ca cifră ridicată (de ex. 7⁵ = 7,5 cm).","source":{"kind":"sarbu+curs_extins","page":68},"source_text":"Sârbu (2017), p. 68 + precizare din Cursul extins","tags":["U10","tip::definitie","sursa::Sarbu+Curs_extins"]},{"id":"GD-U10-064","unit":10,"type":"capcana","front":"Cifra ridicată a milimetrilor într-o cotă (12⁵) este o putere?","back":"Nu. E doar o convenție tipografică: 12⁵ înseamnă 12,5 cm.","source":{"kind":"curs_extins","pdf_page":101},"source_text":"Curs universitar extins, p. PDF 101","tags":["U10","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U10-065","unit":10,"type":"definitie","front":"Care e distanța minimă dintre liniile de cotă?","back":"Minimum 7 mm, atât între două linii de cotă succesive, cât și între linia de cotă cea mai apropiată și elementul cotat.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-066","unit":10,"type":"definitie","front":"Cum se marchează capetele dimensiunii pe linia de cotă?","back":"Prin puncte, linii scurte la 45° sau săgeți, la intersecția cu linia ajutătoare.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-067","unit":10,"type":"definitie","front":"Când se folosesc liniile ajutătoare și cum se trasează?","back":"Când linia de cotă nu taie conturul elementului; delimitează porțiunile cotate și sunt perpendiculare pe liniile de cotă.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-068","unit":10,"type":"definitie","front":"Când se folosesc liniile de indicație (de referință)?","back":"Când spațiul dintre capetele liniei de cotă nu ajunge pentru înscrierea cotei.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-069","unit":10,"type":"definitie","front":"Ce este cota de nivel?","back":"Valoarea numerică a diferenței de înălțime dintre un punct al construcției și un reper de nivel stabilit. Dimensiunile pe verticală ale clădirilor se dau curent prin cote de nivel.","source":{"kind":"sarbu","page":68},"source_text":"Sârbu (2017), p. 68","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-070","unit":10,"type":"definitie","front":"Ce sunt cotele de nivel absolute și relative?","back":"Absolute: reperul este nivelul Mării Negre.\nRelative: reperul este pardoseala finită a parterului corpului principal: cota zero, notată ±0,00 (Sârbu, p. 69, Fig. 10.2.11).","source":{"kind":"sarbu","page":69},"source_text":"Sârbu (2017), p. 69","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-071","unit":10,"type":"definitie","front":"Cum se scriu cotele de nivel?","back":"În metri, cu două zecimale (chiar dacă sunt zero), indiferent cum sunt înscrise celelalte dimensiuni. Deasupra reperului cu semnul +, sub reper cu semnul −.","source":{"kind":"sarbu","page":69},"source_text":"Sârbu (2017), p. 69","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-072","unit":10,"type":"definitie","front":"Cum se desenează simbolul cotei de nivel?","back":"Simbol triunghiular cu înălțimea egală cu înălțimea cifrelor de cotă. În proiecții verticale: vârful pe linia nivelului, cota deasupra brațului orizontal. În proiecții orizontale: simbolul se completează cu un dreptunghi în care se scrie cota.","source":{"kind":"sarbu","page":69},"source_text":"Sârbu (2017), p. 69","tags":["U10","tip::definitie","sursa::Sarbu"]},{"id":"GD-U10-073","unit":10,"type":"capcana","front":"Convențiile din Unitatea 10 (STAS 1-84 etc.) sunt standardele în vigoare azi?","back":"Manualul nu permite această concluzie. Le folosești ca programa cursului din 2017; pentru un desen profesional actual verifici edițiile de standarde aplicabile.","source":{"kind":"curs_extins","pdf_page":99},"source_text":"Curs universitar extins, p. PDF 99","tags":["U10","tip::capcana","sursa::Curs_extins"]},{"id":"GD-U10-074","unit":10,"type":"lucrare","front":"Lucrarea de verificare nr. 10: ce cerințe are și cu ce punctaj?","back":"1. Categoriile de formate, cu exemple (2 p)\n2. Tipurile de indicatoare și dimensiunile (2 p)\n3. Tipurile de linii (2 p)\n4. Scara de reprezentare, cu exemplu (2 p)\n5. Cota unui desen: ce reprezintă, cum se scrie (2 p)","source":{"kind":"sarbu","page":71},"source_text":"Sârbu (2017), p. 71","tags":["U10","tip::lucrare","sursa::Sarbu","lucrare::L10"]}],"exercises":[{"id":"1.1","unit":1,"title":"Proiecție centrală și paralelă","data":"În secțiunea (u,z), planul P este z=0. A=(2;3), B=(4;3), S=(0;6); direcția paralelă Δ=(1;−2).","tasks":["1. În două desene, trasează P, A, B și segmentul AB.","2. Pentru proiecția centrală, construiește SA și SB până la P. Notează imaginile a și b.","3. Pentru proiecția paralelă, construiește proiectantele prin A și B în direcția Δ. Măsoară ab în ambele cazuri."],"check":"ab central = ____ ; ab paralel = ____ ; AB = ____.","solution":{"title":"Proiecție centrală și paralelă","steps":["Central: a=(4;0), b=(8;0), deci ab=4, pe când AB=2.","Paralel cu Δ=(1;−2): a=(3,5;0), b=(5,5;0), deci ab=2.","Grafic: cele două familii de proiectante au orientări diferite; verificare în planșa P01."],"plan":"P01"}},{"id":"1.2","unit":1,"title":"Trei proiecții ale punctului","data":"A=(3;2;4), B=(2;−3;1), C=(1;2;−2).","tasks":["1. Calculează pentru fiecare punct proiecțiile pe H, V și W.","2. Identifică semiplanele HA/HP și VS/VI, respectiv cadranul WI–WIV.","3. Construiește în axonometrie triedrul H–V–W și punctul A cu proiectantele sale."],"check":"","solution":{"title":"Trei proiecții ale punctului","steps":["A: a=(3;2;0), a′=(3;0;4), a″=(0;2;4): HA, VS, WI.","B: b=(2;−3;0), b′=(2;0;1), b″=(0;−3;1): HP, VS, WII.","C: c=(1;2;0), c′=(1;0;−2), c″=(0;2;−2): HA, VI, WIV."],"plan":null}},{"id":"1.3","unit":1,"title":"Lungime reală și proiecții","data":"A=(1;1;1), B=(4;5;3). Repetă pentru C=(1;1;3), D=(4;5;3).","tasks":["1. Calculează Δx, Δy, Δz și lungimea AB.","2. Calculează lungimile pe H, V și W; marchează-le într-o schiță cu proiecții.","3. Compară cu CD și explică ce proiecție redă lungimea reală."],"check":"AB ____ ; ab ____ ; a′b′ ____ ; a″b″ ____ ; CD ____.","solution":{"title":"Lungime reală și proiecții","steps":["Pentru AB: (Δx,Δy,Δz)=(3;4;2), |AB|=√29≈5,385.","Pe H: 5; pe V: √13≈3,606; pe W: √20≈4,472. Niciuna nu este 5,385.","Pentru CD: (3;4;0), |CD|=|cd|=5; pe H rezultă adevărata mărime."],"plan":null}},{"id":"2.1","unit":2,"title":"Epura punctelor din patru diedre","data":"A=(4;2;3), B=(3;−2;1), C=(2;−1;−3), D=(1;3;−2).","tasks":["1. Trasează o singură axă OX; alege originea O astfel încât abscisele pozitive să încapă spre stânga.","2. Construiește a/a′, b/b′, c/c′, d/d′ cu liniile de ordine.","3. Notează diedrul și verifică semnele y și z pentru fiecare punct."],"check":"","solution":{"title":"Epura punctelor din patru diedre","steps":["A: I — a sub OX la 2; a′ sus la 3; abscisa +4.","B: II — b sus la 2; b′ sus la 1; abscisa +3.","C: III — c sus la 1; c′ jos la 3; abscisa +2.","D: IV — d jos la 3; d′ jos la 2; abscisa +1. Planșa P02."],"plan":"P02"}},{"id":"2.2","unit":2,"title":"Transferul proiecției laterale","data":"Folosind A=(4;2;3) și B=(3;−2;1) din problema 2.1. Coordonatele sunt în metri; pentru desenul de mână folosește scara 1 m în spațiu = 1 cm pe hârtie (1:100).","tasks":["1. Construiește pe epura existentă axa OZ și poziția rabătută a planului W.","2. Transferă |y| din planul H spre W cu arc având centrul în O.","3. Plasează a″ și b″ și trasează proiectantele orizontale din a′ și b′."],"check":"","solution":{"title":"Transferul proiecției laterale","steps":["a″=(0;2;3) m: la 2 cm la dreapta lui OZ și la 3 cm deasupra OX, la scara 1:100.","b″=(0;−2;1) m: la 2 cm la stânga lui OZ și la 1 cm deasupra OX, la scara 1:100.","Distanțele față de OZ sunt 2 pentru ambele; a′/a″ și b′/b″ au aceeași cotă."],"plan":null}},{"id":"2.3","unit":2,"title":"Punctele în plane bisectoare","data":"E=(5;2;2), F=(3;−2,5;2,5), G=(2;1,5;−1,5).","tasks":["1. Construiește perechile de proiecții pe epură.","2. Stabilește bisectorul (B1 sau B2) și diedrul pentru fiecare.","3. Marchează perechile simetrice și cele suprapuse."],"check":"","solution":{"title":"Punctele în plane bisectoare","steps":["E: z=y=2 — B1, diedrul I; e/e′ simetrice față de OX.","F: z=−y=2,5 — B2, diedrul II; f=f′ deasupra OX.","G: z=−y=−1,5 — B2, diedrul IV; g=g′ sub OX."],"plan":null}},{"id":"2.4","unit":2,"title":"Simetria punctului","data":"P=(3;1;2).","tasks":["1. Construiește epura punctului P și apoi reflectă-l față de H, V și OX.","2. Calculează separat coordonatele simetricelor față de B1 și B2; desenează proiecțiile.","3. Testează fiecare transformare aplicând-o de două ori."],"check":"După două reflexii identice, coordonatele revin la P? ___","solution":{"title":"Simetria punctului","steps":["Față de H: (3;1;−2), diedrul IV; față de V: (3;−1;2), diedrul II.","Față de OX: (3;−1;−2), diedrul III; față de B1: (3;2;1), diedrul I.","Față de B2: (3;−2;−1), diedrul III; fiecare reflexie este involutivă."],"plan":null}},{"id":"3.1","unit":3,"title":"Urmele unei drepte","data":"A=(3;1;1), B=(5;3;−1).","tasks":["1. Construiește a, a′, b, b′ și proiecțiile d=ab, d′=a′b′; prelungește d și d′.","2. Obține grafic urmele h/h′ și v/v′ prin intersecții cu OX și linii de ordine.","3. Calculează urma W și precizează în ce diedre se găsesc intervalele dreptei."],"check":"","solution":{"title":"Urmele unei drepte","steps":["D(t)=(3+2t;1+2t;1−2t). H la t=0,5: (4;2;0); V la t=−0,5: (2;0;2).","W la t=−1,5: (0;−2;4). În epură: h la x=4 sub OX la 2; v′ la x=2 sus la 2; w″ stânga OZ la 2, sus la 4.","Diedre la t crescător: II → I → IV, frontierele fiind V și H. |AB|=√12≈3,464. Planșa P03."],"plan":"P03"}},{"id":"3.2","unit":3,"title":"Cinci poziții particulare ale dreptei","data":"a) C=(2;1;2), D=(5;3;2); b) E=(2;3;1), F=(2;3;4); c) G=(1;1;3), K=(4;1;3); d) L=(3;1;1), N=(5;1;3); e) P=(2;1;3), R=(2;4;3).","tasks":["1. Pentru a–e, identifică tipul dreptei și schițează proiecțiile de același nume.","2. Calculează pe ce plan se vede lungimea reală a segmentului.","3. Construiește urma cerută: a) V; b) H; c) W; d) H; e) V."],"check":"","solution":{"title":"Cinci poziții particulare ale dreptei","steps":["a) Orizontală: |CD|=√13 pe H; V=(0,5;0;2).","b) Verticală: EF=3 pe V și W; H=(2;3;0), proiecție H punctuală.","c) Fronto-orizontală: GK=3 pe H și V; W=(0;1;3).","d) Frontală: |LN|=√8 pe V; H=(2;1;0).","e) Dreaptă de capăt: |PR|=3 pe H și W; V=(2;0;3), proiecția pe V este un punct."],"plan":null}},{"id":"3.3","unit":3,"title":"Două drepte: paralelism și concurență","data":"a) D₁: (1;1;1), (3;2;3); D₂: (2;3;1), (4;4;3). b) D₁: (2;1;1), (4;3;3); D₂: (1;3;1), (5;1;3). c) D₁: (1;1;1), (3;2;3); D₃: (2;0;3), (4;3;1).","tasks":["1. Construiește pe H și V cele trei perechi, în desene separate.","2. Identifică relația spațială și susține-o prin vectori sau un punct comun.","3. La cazul c), compară abscisele intersecțiilor proiectate."],"check":"","solution":{"title":"Două drepte: paralelism și concurență","steps":["a) Paralele distincte: ambii directori (2;1;2), dar punctul (2;3;1) nu aparține primei drepte.","b) Concurente: K=(3;2;2), comun ambelor drepte; k și k′ la abscisa +3.","c) Necoplanare: pe H intersecție la x=3,5, pe V la x=2,5; directori (2;1;2) și (2;3;−2) necoliniari."],"plan":null}},{"id":"3.4","unit":3,"title":"Capcana dreptei de profil","data":"D₁(t)=(3;t;1+t), D₂(s)=(s;1;3).","tasks":["1. Construiește ambele proiecții pe H și V.","2. Determină intersecțiile aparente și compară liniile de ordine.","3. Verifică pe W și rezolvă ecuațiile pentru un punct comun."],"check":"","solution":{"title":"Capcana dreptei de profil","steps":["Pe H: (x,y)=(3;1); pe V: (x,z)=(3;3). Abscisele aparente coincid.","În spațiu x cere s=3 și y cere t=1, dar z(D₁)=2 ≠ z(D₂)=3.","Pe W: d₁″ este z=y+1; proiecția lui D₂ este punctul (1;3), exterior lui d₁″. Dreptele nu sunt concurente."],"plan":null}},{"id":"4.1","unit":4,"title":"Urmele planului P","data":"Pentru problemele 4.1–4.4: P: 2x+3y+3z=12.","tasks":["1. Calculează Px, Py, Pz.","2. Construiește în epură Ph și Pv și apoi urma Pw pe W, transferând Py.","3. Verifică intersecția urmelor pe OX."],"check":"","solution":{"title":"Urmele planului P","steps":["Px=(6;0;0), Py=(0;4;0), Pz=(0;0;4).","Ph: 2x+3y=12, z=0; Pv: 2x+3z=12, y=0; Pw: y+z=4, x=0.","Ph și Pv întâlnesc OX la x=6; Pw unește Py și Pz în W."],"plan":null}},{"id":"4.2","unit":4,"title":"Puncte de pe o orizontală a planului","data":"P: 2x+3y+3z=12. M=(3;1;1), N=(3;2;1).","tasks":["1. Pe Pv identifică punctul de cotă z=1 și construiește proiecția H a orizontalei de cotă 1.","2. Verifică grafic dacă m și n aparțin acestei orizontale.","3. Controlează prin substituție în ecuația planului."],"check":"","solution":{"title":"Puncte de pe o orizontală a planului","steps":["La z=1: 2x+3y=9; pe V punctul de referință este x=4,5.","M: 6+3+3=12, deci aparține; N: 6+6+3=15, deci nu aparține.","În H, la abscisa x=3, orizontala are y=1, nu y=2."],"plan":null}},{"id":"4.3","unit":4,"title":"Intersecția a două plane","data":"P: 2x+3y+3z=12 și Q: 2x+2y+z=10.","tasks":["1. Construiește urmele Ph, Pv, Qh, Qv în aceeași epură.","2. Găsește urma Hᵢ ca intersecție Ph∩Qh și urma Vᵢ ca intersecție Pv∩Qv.","3. Construiește i și i′ și verifică două puncte pe ambele plane."],"check":"","solution":{"title":"Intersecția a două plane","steps":["Qh: x+y=5; Qv: 2x+z=10.","Hᵢ=(3;2;0); Vᵢ=(4,5;0;1). i unește hᵢ cu vᵢ, iar i′ unește hᵢ′ cu vᵢ′.","Control: în P, Hᵢ dă 6+6=12 și Vᵢ dă 9+3=12; în Q, 6+4=10 și 9+1=10. Planșa P04."],"plan":"P04"}},{"id":"4.4","unit":4,"title":"Intersecție dreaptă–plan prin auxiliar frontal","data":"P: 2x+3y+3z=12. Dreapta D trece prin A=(1;1;2), B=(3;1;4).","tasks":["1. Construiește proiecțiile d, d′ și notează depărtarea constantă.","2. Alege planul auxiliar y=1; construiește intersecția acestuia cu P.","3. Obține K ca intersecție dreaptă–plan; verifică în cele două ecuații."],"check":"","solution":{"title":"Intersecție dreaptă–plan prin auxiliar frontal","steps":["În auxiliarul y=1: 2x+3z=9; dreapta D are z=x+1, y=1.","Rezultă x=1,2, z=2,2, deci K=(1,2;1;2,2).","Control: în P, 2,4+3+6,6=12; pe D, parametrul este t=0,1 dacă D=A+t(B−A)."],"plan":null}},{"id":"5.1","unit":5,"title":"Schimbarea planului vertical","data":"A=(1;1;1), B=(4;5;3).","tasks":["1. Construiește epura inițială și segmentul orizontal ab.","2. Trasează O₁X₁ paralel cu ab și du din a, b proiectante perpendiculare.","3. Reportează cotele pe noua vedere și măsoară lungimea reală și înclinarea față de H."],"check":"","solution":{"title":"Schimbarea planului vertical","steps":["Pe H: |ab|=√(3²+4²)=5; Δz=2.","Pe noul V₁, |a₁′b₁′|=√(5²+2²)=√29≈5,385.","Înclinarea segmentului față de H este arctan(2/5)≈21,80°."],"plan":null}},{"id":"5.2","unit":5,"title":"Rotația de nivel a segmentului AB","data":"A=(1;1;1), B=(4;5;3); axa verticală de rotație trece prin A.","tasks":["1. Rotește proiecția b în jurul lui a, pe un arc cu raza |ab|, până când ab₁ este paralel cu OX.","2. Alege b₁ spre stânga lui a; transferă cota inițială a lui B pentru b₁′.","3. Măsoară a′b₁′ și compară cu problema 5.1."],"check":"","solution":{"title":"Rotația de nivel a segmentului AB","steps":["ab=5; b₁=(6;1) în H, la abscisa +6 și depărtarea +1.","B₁=(6;1;3), deoarece rotația de nivel păstrează z.","|a′b₁′|=√29≈5,385, ca la schimbarea planului V."],"plan":null}},{"id":"5.3","unit":5,"title":"Rotația de front a segmentului CD","data":"C=(1;1;1), D=(3;3;4); axa de capăt de rotație trece prin C.","tasks":["1. În V, rotește d′ în jurul lui c′ pe cercul de rază |c′d′| până când c′d₁′ devine paralel cu OX.","2. Alege d₁′ spre stânga lui c′; pe H păstrează depărtarea inițială a lui D.","3. Măsoară |cd₁| și verifică prin calcul lungimea reală CD."],"check":"","solution":{"title":"Rotația de front a segmentului CD","steps":["|c′d′|=√((3−1)²+(4−1)²)=√13≈3,606.","După rotație: d₁′ are x=1+√13≈4,606 și z=1; d₁ pe H are y=3.","|cd₁|=√(13+4)=√17≈4,123=|CD|."],"plan":null}},{"id":"5.4","unit":5,"title":"Rabaterea unui triunghi dintr-un plan de capăt","data":"P: z=x−1; A=(2;1;1), B=(4;1;3), C=(3;3;2).","tasks":["1. Trasează Ph, Pv și proiecțiile a/a′, b/b′, c/c′.","2. Rabatere în jurul urmei Ph: pentru fiecare punct reportează cu compasul raza |Px p′| pe paralela la OX prin p.","3. Construiește A₀B₀C₀ în H și măsoară cele trei lungimi reale."],"check":"","solution":{"title":"Rabaterea unui triunghi dintr-un plan de capăt","steps":["Ph: x=1; Pv: z=x−1. Abscisa rabătută este x₀=1+√2·(x−1).","A₀=(1+√2;1), B₀=(1+3√2;1), C₀=(1+2√2;3).","AB=√8≈2,828; AC=BC=√6≈2,449. Triunghi isoscel. Planșa P05.","Sensul rabaterii se alege. În Fig. 5.4.3 (Sârbu 2017, p. 42), punctul rabătut este de partea opusă urmei Ph: x₀=1−(x−1)√2. Atunci A₀=(1−√2;1), B₀=(1−3√2;1), C₀=(1−2√2;3). Lungimile reale ale triunghiului sunt aceleași. P05 arată ambele sensuri."],"plan":"P05"}},{"id":"6.1","unit":6,"title":"Prismă dreaptă triunghiulară","data":"Baza ABC în H: A=(1;1;0), B=(4;1;0), C=(2;3;0). Muchiile laterale sunt verticale și au lungimea 3.","tasks":["1. Calculează coordonatele lui A₁, B₁, C₁.","2. Construiește epura H–V cu bazele și muchiile laterale.","3. În V, stabilește liniile vizibile privind dinspre +OY și marchează eventualele suprapuneri."],"check":"","solution":{"title":"Prismă dreaptă triunghiulară","steps":["A₁=(1;1;3), B₁=(4;1;3), C₁=(2;3;3). Pe H, muchiile laterale degenerează în puncte.","În V, c′c₁′ este vizibilă (y=3, în fața bazei cu y=1); conturul orizontal la z=0 și z=3 este vizibil.","Muchia bazei și cea de sus au proiectări suprapuse cu segmente ale conturului; separă corect geometria de simbolul liniilor."],"plan":null}},{"id":"6.2","unit":6,"title":"Prismă oblică — model complet și vizibilitate","data":"Baza ABC în H: A=(1;1;0), B=(3;1;0), C=(2;3;0). Vectorul complet de translație către baza superioară este v=(2;1;3).","tasks":["1. Calculează A₁=A+v, B₁=B+v, C₁=C+v; construiește ambele proiecții.","2. Determină conturul aparent pe H și pe V.","3. Privind pe H dinspre +OZ și pe V dinspre +OY, desenează întrerupt muchiile acoperite."],"check":"","solution":{"title":"Prismă oblică — model complet și vizibilitate","steps":["A₁=(3;2;3), B₁=(5;2;3), C₁=(4;4;3).","Pe H, conturul aparent este a–b–b₁–c₁–c–a; muchia BC este acoperită; celelalte muchii proiectate sunt vizibile în această configurație.","Pe V, conturul aparent este a′–b′–b₁′–a₁′; c′c₁′ este vizibilă; nu există alte muchii acoperite distincte. Planșa P06."],"plan":"P06"}},{"id":"6.3","unit":6,"title":"Piramidă patrulateră și vizibilitate","data":"Baza ABCD în H: A=(1;1;0), B=(4;1;0), C=(4;4;0), D=(1;4;0). Vârful S=(2;2;4).","tasks":["1. Construiește epura bazei și proiecția vârfului S.","2. Unește S cu A,B,C,D și stabilește vizibilitatea în H și V.","3. Calculează lungimile reale SA, SB, SC, SD (vor fi folosite la 9.2)."],"check":"","solution":{"title":"Piramidă patrulateră și vizibilitate","steps":["|SA|=√18≈4,243; |SB|=√21≈4,583; |SC|=√24≈4,899; |SD|=√21≈4,583.","Pe H sunt vizibile muchiile laterale; s este în interiorul bazei.","În V, proiecția SA se suprapune peste SD, iar SB peste SC; fețele dinspre +OY acoperă fețele din spate, fără a genera linii ascunse distincte în epură. Planșa P07."],"plan":"P07"}},{"id":"6.4","unit":6,"title":"Verificarea relației lui Euler","data":"Prismă triunghiulară; piramidă patrulateră; octaedru regulat.","tasks":["1. Desenează schematic fiecare poliedru și numără vârfurile V, muchiile E și fețele F.","2. Completează trei verificări V−E+F.","3. Verifică numărul de muchii numărând fiecare muchie o singură dată."],"check":"","solution":{"title":"Verificarea relației lui Euler","steps":["Prismă triunghiulară: 6−9+5=2.","Piramidă patrulateră: 5−8+5=2.","Octaedru: 6−12+8=2."],"plan":null}},{"id":"7.1","unit":7,"title":"Cilindru vertical: puncte de pe manta","data":"Axa: x=3, y=2. R=1,5, baza z=0, înălțime 4. N: n=(3;3,5), z=2,5. Q: q=(3;0,5), z=1.","tasks":["1. Construiește conturul cilindrului pe H și V.","2. Marchează n și q pe cercul din H; construiește n′ și q′ folosind cotele date.","3. Privind dinspre +OY, stabilește care punct este vizibil și care este acoperit."],"check":"","solution":{"title":"Cilindru vertical: puncte de pe manta","steps":["Pe H, cercul are centrul (3;2) și raza 1,5; pe V conturul are x de la 1,5 la 4,5, z de la 0 la 4.","N=(3;3,5;2,5), pe generatoarea frontală: vizibil în V.","Q=(3;0,5;1), pe generatoarea posterioară: acoperit în V; din n sau q singur nu poți afla z."],"plan":null}},{"id":"7.2","unit":7,"title":"Con drept: proiecția unui punct prin generatoare","data":"Baza în H: centru (3;2), R=2; vârful S=(3;2;4). K pe manta are k=(4;2); L are l=(3;3).","tasks":["1. Construiește cercul de bază în H și conturul triunghiular în V.","2. Pentru K, găsește piciorul generatoarei pe cerc și construiește k′.","3. Pentru L, construiește cercul de nivel corespunzător și determină l′."],"check":"","solution":{"title":"Con drept: proiecția unui punct prin generatoare","steps":["K: distanța față de axa conului este 1; piciorul generatoarei pe bază E=(5;2;0); z(K)=2.","L: la aceeași distanță radială 1, cercul de nivel este la cota 2; L=(3;3;2).","În V, k′ la abscisa 4 și z=2; l′ la abscisa 3 și z=2; ambele sunt vizibile dinspre +OY. Planșa P08."],"plan":"P08"}},{"id":"7.3","unit":7,"title":"Sferă: secțiune de nivel și cote posibile","data":"G=(4;3;3), R=2,5; planul z=4,5. Un punct are proiecția H p=(5;3).","tasks":["1. Construiește cele două contururi ale sferei.","2. Calculează raza cercului de nivel și desenează proiecțiile acestuia.","3. Determină cele două cote ale punctului cu proiecția p; marchează punctul vizibil din +OZ."],"check":"","solution":{"title":"Sferă: secțiune de nivel și cote posibile","steps":["Diferența față de centru este 1,5; raza cercului de nivel este √(2,5²−1,5²)=2.","Pe H cerc de rază 2; pe V segment orizontal de lungime 4 la cota 4,5.","Pentru p=(5;3), z=3±√5,25, deci aproximativ 5,291 ori 0,709; vizibil din +OZ este cel de sus. Planșa P09."],"plan":"P09"}},{"id":"8.1","unit":8,"title":"Secțiunea unei prisme prin plan de capăt","data":"Prisma dreaptă din 6.1: A=(1;1;0), B=(4;1;0), C=(2;3;0), înălțime 3. Plan secant P: z=0,5x+0,5.","tasks":["1. Construiește pe V urma Pv și intersecteaz-o cu cele trei muchii laterale proiectate.","2. Coboară liniile de ordine pentru proiecțiile H ale punctelor A*, B*, C*.","3. Rabate planul P pe H și măsoară laturile reale ale secțiunii."],"check":"","solution":{"title":"Secțiunea unei prisme prin plan de capăt","steps":["Urma Ph: x=−1; Pv: z=0,5x+0,5.","A*=(1;1;1), B*=(4;1;2,5), C*=(2;3;1,5).","La rabatere x₀=−1+(x+1)√1,25: A₀≈(1,236;1); B₀≈(4,590;1); C₀≈(2,354;3).","Laturi reale: A*B*=√11,25≈3,354; A*C*=√5,25≈2,291; B*C*=3.","Este corect și sensul opus, ilustrat în Sârbu, Fig. 5.4.3: x₀=−1−(x+1)√1,25, y₀=y. Rezultă A₀≈(−3,236;1), B₀≈(−6,590;1), C₀≈(−4,354;3). Lungimile reale nu se schimbă."],"plan":null}},{"id":"8.2","unit":8,"title":"Secțiunea cilindrului: opt generatoare","data":"Cilindru drept circular: axa prin (3;2), R=1, 0≤z≤4. Plan P: z=x−0,5.","tasks":["1. Construiește cercul H și urma Pv; împarte cercul în opt părți egale începând la x maxim.","2. Pentru fiecare generatoare la 0°,45°,...,315°, construiește punctul de secțiune.","3. Unește punctele în H prin cercul proiectat și identifică proiecția V; reprezintă adevărata formă prin rabatere."],"check":"","solution":{"title":"Secțiunea cilindrului: opt generatoare","steps":["Parametric: X(θ)=(3+cosθ;2+sinθ;2,5+cosθ), pentru θ∈[0,2π].","Pe V: segmentul z=x−0,5, 2≤x≤4, 1,5≤z≤3,5; pe H: cercul de rază 1.","În planul secant: elipsă cu semiaxele √2 și 1; perimetru aproximativ 7,640. La 0°,45°,...: z=3,50;3,21;2,50;1,79;1,50;1,79;2,50;3,21. Planșa P10."],"plan":"P10"}},{"id":"8.3","unit":8,"title":"Secțiuni conice: decizia prin poziția planului","data":"Conul drept circular dublu ideal are R=2 și înălțimea unei pânze h=4. Consideră numai secțiuni nedegenerate cu plane care nu trec prin vârf.","tasks":["1. Calculează semiunghiul θ al generatoarei cu axa.","2. Clasifică secțiunea pentru un plan cu axa la unghiul α: a) 90°; b) 45°; c) α=θ; d) 0°.","3. Pentru conul finit cu baza z=0, h=4, determină raza secțiunii orizontale la cota z=1."],"check":"","solution":{"title":"Secțiuni conice: decizia prin poziția planului","steps":["θ=arctan(2/4)≈26,565°.","a) cerc; b) elipsă (45°>θ); c) parabolă; d) hiperbolă pentru planul ales să intersecteze ambele pânze ale conului dublu.","Pe conul finit, secțiunile pot apărea numai ca porțiuni ale acestor curbe dacă ating mantaua. La z=1, r=2(1−1/4)=1,5."],"plan":null}},{"id":"8.4","unit":8,"title":"Două suprafețe: pătrundere, contact, smulgere","data":"Extensie (suport extins): intersecție calculată analitic. Cilindrul vertical infinit: x²+y²=4. Cilindrul orizontal infinit: (y−d)²+z²=1, axă paralelă cu OX prin (0;d;0). Cazuri d=0; 1; 1,5.","tasks":["1. Schițează poziția celor două axe și secțiunile lor circulare.","2. Pentru fiecare d verifică dacă intersecția constă din două componente, contact intermediar sau o singură componentă.","3. Marchează punctele unde x=0 (dacă există), la care ramurile se reunesc."],"check":"","solution":{"title":"Două suprafețe: pătrundere, contact, smulgere","steps":["d=0: y∈[−1;1], x=±√(4−y²) niciodată 0 ⇒ două curbe disjuncte (pătrundere).","d=1: y≤2 și x=0 doar în punctul (0;2;0), unde suprafețele admit planul tangent comun y=2, iar curba prezintă un punct dublu, cu tangente distincte x=±√2·z (caz intermediar).","d=1,5: |y|≤2 limitează curba cilindrului mic; ramurile x± se reunesc la (0;2;±√0,75) ⇒ o componentă (smulgere). Planșa P11."],"plan":"P11"}},{"id":"9.1","unit":9,"title":"Desfășurarea unei prisme trunchiate","data":"Prisma dreaptă ABC–A₁B₁C₁ din 6.1, secționată ca în 8.1. Baza A=(1;1), B=(4;1), C=(2;3). Cotele tăierii sunt la A=1, B=2,5, C=1,5. Datele spațiale și lungimile rezultate sunt în metri (m); ariile în m².","tasks":["1. Alege drept tăietură muchia AA₁ și trasează orizontal succesiunea AB, BC, CA, în lungimi reale.","2. În pozițiile A–B–C–A ridică generatoare de înălțimi 1;2,5;1,5;1.","3. Unește vârfurile suprafeței superioare; calculează lungimile și aria desfășurării."],"check":"","solution":{"title":"Desfășurarea unei prisme trunchiate","steps":["AB=3, BC=√8≈2,828, CA=√5≈2,236; perimetru 3+√8+√5≈8,064.","Poziții pe linie: 0; 3; 5,828; 8,064. Înălțimi: 1;2,5;1,5;1.","Aria laterală exactă = 3·(1+2,5)/2 + √8·(2,5+1,5)/2 + √5·(1,5+1)/2 ≈13,702 m²."],"plan":null}},{"id":"9.2","unit":9,"title":"Desfășurarea piramidei prin triunghiuri","data":"Piramida din 6.3: baza pătrată de latură 3 și vârful S=(2;2;4). Muchii laterale: SA=√18, SB=SD=√21, SC=√24.","tasks":["1. Taie mantaua pe muchia SA; cu compasul construiește fețele SAB, SBC, SCD, SDA din trei laturi.","2. Notează laturile comune și repetarea punctului A la închiderea șirului de triunghiuri.","3. Măsoară unghiurile la S și calculează suma."],"check":"","solution":{"title":"Desfășurarea piramidei prin triunghiuri","steps":["Fețe SAB/SDA: unghi la S ≈39,5097°; SBC/SCD: ≈36,6992°.","Suma unghiurilor la vârf ≈152,418°, sub 360°; toate laturile bazei =3.","Muchia SA este duplicată la cele două capete ale desfășurării. Planșa P12."],"plan":"P12"}},{"id":"9.3","unit":9,"title":"Desfășurarea mantalei cilindrice tăiate","data":"Cilindrul din 8.2: R=1, plan de tăiere z=x−0,5; parametrizează x=3+cosθ. Deschide mantaua pe generatoarea θ=0.","tasks":["1. În desen plan, trasează axa orizontală s de lungime 2πR și împarte-o în opt intervale egale.","2. Pe fiecare generatoare verticală din desfășurare reportează cota z(θ)=2,5+cosθ.","3. Trasează prin puncte curba marginii superioare și verifică închiderea ei la θ=2π."],"check":"","solution":{"title":"Desfășurarea mantalei cilindrice tăiate","steps":["s=Rθ=θ; lățimea totală 2π≈6,283.","La θ=0,π/4,π/2,3π/4,π,5π/4,3π/2,7π/4,2π, z≈3,50;3,21;2,50;1,79;1,50;1,79;2,50;3,21;3,50.","Marginea este curba z(s)=2,5+cos s, nu o polilinie cu opt laturi. Lungimea curbei ≈7,640 (perimetrul elipsei din 8.2). Planșa P13."],"plan":"P13"}},{"id":"9.4","unit":9,"title":"Desfășurarea mantalei conului drept","data":"R=1, h=2√2. Conul este drept circular, mantaua fiind tăiată pe o generatoare.","tasks":["1. Calculează lungimea reală a generatoarei G.","2. Calculează unghiul sectorului circular din desfășurare.","3. Cu compasul și raportorul construiește sectorul și verifică lungimea arcului."],"check":"","solution":{"title":"Desfășurarea mantalei conului drept","steps":["G=√(R²+h²)=√(1+8)=3.","φ=360°·R/G=120°; lungimea arcului 3·(2π/3)=2π, egală cu circumferința bazei."],"plan":null}},{"id":"10.1","unit":10,"title":"Calcule de scară","data":"a) Zid 12,50 m la 1:100. b) Grindă 35 cm la 1:20. c) Pe plan 1:200 măsori 48 mm. d) Fațadă 18 m pe lățime utilă ≤400 mm.","tasks":["1. Calculează a) și b) în milimetri pe hârtie.","2. Calculează c) lungimea reală în metri.","3. Alege d) o scară uzuală permisă de seria din manual și calculează lungimea desenului."],"check":"","solution":{"title":"Calcule de scară","steps":["a) 12 500/100=125 mm; b) 350/20=17,5 mm.","c) 48·200=9 600 mm=9,60 m.","d) 18 000/400=45; alegere uzuală 1:50, reprezentare 360 mm (<400)."],"plan":null}},{"id":"10.2","unit":10,"title":"Format, chenar și indicator","data":"Folosind convențiile din Unitatea 10 a manualului Sârbu (2017): determină formatul A2 și A3×3 și indicatorul pentru A2 și A4. Desenează A4 la scara 1:2.","tasks":["1. Notează dimensiunile formatelor A2 și A3×3.","2. Pe A4 la scara 1:2 trasează marginea, zona neutră, chenarul, fâșia de îndosariere și indicatorul mic.","3. Înscrie dimensiunile reale și cele de trasare în desen."],"check":"","solution":{"title":"Format, chenar și indicator","steps":["A2: 420×594 mm; A3×3: 420×891 mm.","A2: indicator mare 185×50 mm; A4: indicator mic 120×40 mm (convenția cursului din 2017).","La 1:2: A4 devine 105×148,5 mm; zona neutră 5→2,5 mm; fâșia de îndosariere 20→10 mm; indicatorul mic 120×40→60×20 mm."],"plan":null}},{"id":"10.3","unit":10,"title":"Elevația unui perete complet determinat","data":"Perete 6,45 m lungime, 2,80 m înălțime, vedere frontală. Ușa: de la x=0,90 la 1,80 m, z=0–2,10 m. Fereastra: x=3,30–4,50 m, z=0,90–2,10 m. Pardoseală ±0,00.","tasks":["1. Pe A4 la scara 1:50 trasează peretele și contururile celor două goluri, folosind coordonatele date.","2. Cotează lungimea totală, segmentele dintre goluri și înălțimile: pardoseală, parapet, buiandrug, partea superioară.","3. Verifică faptul că suma cotelor orizontale parțiale este egală cu 6,45 m."],"check":"","solution":{"title":"Elevația unui perete complet determinat","steps":["Perete pe hârtie: 6450/50=129 mm lungime, 2800/50=56 mm înălțime.","Ușa: lățime 900/50=18 mm, înălțime 2100/50=42 mm; fereastra: 1200/50=24 mm, înălțime 24 mm; parapet 900/50=18 mm.","Înscrierea lanțului de cote: 90 | 90 | 1,50 | 1,20 | 1,95; total 6,45. Sub 1,00 m în cm; de la 1,00 m în metri cu două zecimale (Sârbu 2017, p. 68).","Control aritmetic separat: 0,90 + 0,90 + 1,50 + 1,20 + 1,95 = 6,45 m.","Cote de nivel: ±0,00, +0,90, +2,10, +2,80; simboluri triunghiulare. Sârbu 2017, p. 69 și Fig. 10.2.11 notează reperul ±0,00, la fel ca suportul extins. Planșa P14."],"plan":"P14"}},{"id":"10.4","unit":10,"title":"Linii de desen după convenția Sârbu","data":"Elemente: contur secțiune, muchie vizibilă, muchie acoperită, linie de cotă, hașură, axă de gol de ușă, chenar.","tasks":["1. Completează pentru fiecare element indicativul C1/C2/C3/I2 sau altul corespunzător.","2. Trasează câte un exemplu scurt al fiecărui tip pe liniile de jos.","3. Compară cu convențiile Unității 10 a manualului din 2017, fără a le prezenta drept standarde actuale."],"check":"","solution":{"title":"Linii de desen după convenția Sârbu","steps":["Contur secțiune: C1; muchie vizibilă în vedere: C2; muchie acoperită: I2.","Linie de cotă: C3; hașură: C3; axă gol de ușă: C3; chenar: C1. Acestea sunt notațiile materialului Sârbu (2017), nu o verificare a statutului normativ actual."],"plan":null}}]};
